function readNumoraAccounts(){try{const saved=JSON.parse(localStorage.getItem('numoraAccounts')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))return saved;}catch{}return{};}
function saveNumoraAccount(email,account){const accounts=readNumoraAccounts();accounts[String(email||'').trim().toLowerCase()]=account;localStorage.setItem('numoraAccounts',JSON.stringify(accounts));}
function findNumoraAccount(email){const normalized=String(email||'').trim().toLowerCase();const accounts=readNumoraAccounts();if(accounts[normalized])return accounts[normalized];const match=Object.keys(accounts).find(key=>key.toLowerCase()===normalized);if(match){accounts[normalized]=accounts[match];delete accounts[match];localStorage.setItem('numoraAccounts',JSON.stringify(accounts));return accounts[normalized];}const legacyEmail=localStorage.getItem('numoraEmail');if(legacyEmail&&legacyEmail.trim().toLowerCase()===normalized){const legacy={username:localStorage.getItem('numoraUser')||normalized.split('@')[0]||'Learner',password:localStorage.getItem('numoraPassword')||'',progress:Object.fromEntries(numoraProgressKeys().map(key=>[key,localStorage.getItem(key)]))};saveNumoraAccount(normalized,legacy);return legacy;}return null;}
function localDateKey(date=new Date()){const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`;}
function calculateCurrentStreak(days=[]){const sorted=[...new Set(days)].sort();if(!sorted.length)return 0;const today=Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z');const latest=Date.parse(sorted[sorted.length-1]+'T00:00:00Z');if(!Number.isFinite(latest)||today-latest>86400000||latest>today)return 0;let run=1;for(let i=sorted.length-1;i>0;i--){const current=Date.parse(sorted[i]+'T00:00:00Z'),previous=Date.parse(sorted[i-1]+'T00:00:00Z');if(current-previous!==86400000)break;run++;}return run;}
function accountJoinDateLabel(){const email=localStorage.getItem('numoraActiveEmail');if(!email)return 'Welcome to Numora';const account=findNumoraAccount(email);if(!account)return 'Welcome to Numora';if(!account.joinedAt){let firstPractice='';try{const saved=JSON.parse(account.progress?.numoraBadgeProgress||'{}');firstPractice=(saved.practiceDays||[]).slice().sort()[0]||'';}catch{}account.joinedAt=firstPractice||localDateKey();saveNumoraAccount(email,account);}const [year,month,day]=account.joinedAt.split('-').map(Number);const date=new Date(year,month-1,day);return `Joined ${date.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}`;}
function isNumoraProgressKey(key){return /^(numoraGrade$|numoraFreshStart$|numoraCompleted$|numoraStreak$|numoraAccuracyAttempts$|numoraAccuracyCorrect$|numoraTodayDate$|numoraTodayCompleted$|numoraMonthKey$|numoraMonthCompleted$|numoraBadgeProgress$|numoraXP$|numoraLifetimeXP$|numoraXpHistory$|numoraDailyQuestionHistory$|numoraHintTokens$|numoraHintPacks$|numoraHintCycle:|numoraXpAvatarStar$|numoraXpAvatarItem$|numoraXpOwnedRewards$|numoraDoubleXpAnswers$|numoraLessonIndex_|numoraPausedLesson_|numoraTheme$|numoraAnswerControl$|numoraClickToTypeAnswer$|numoraSavedSkills$|numoraMistakes$|numoraLessonNotes$|numoraDailyGoal$|numoraAutoRead$|numoraAutoFocusAnswer$|numoraAutoExplain$|numoraReduceMotion$|numoraHighContrast$|numoraSoundEffects$|numoraReadingSize$|numoraLessonCelebrations$|numoraLanguage$|numoraCustomQuizLesson$|numoraCustomQuizCount$|numoraStudyPlan$|numoraQuestionBookmarks$)/.test(key);}
function numoraProgressKeys(){return Object.keys(localStorage).filter(isNumoraProgressKey);}
function getXpBalance(){const balance=Number(localStorage.getItem('numoraXP')||0);return Number.isSafeInteger(balance)&&balance>0?balance:0;}
function getLifetimeXp(){let total=Number(localStorage.getItem('numoraLifetimeXP'));if(!Number.isSafeInteger(total)||total<0){total=getXpBalance();localStorage.setItem('numoraLifetimeXP',String(total));saveCurrentAccountProgress();}return total;}
function readXpHistory(){try{const history=JSON.parse(localStorage.getItem('numoraXpHistory')||'[]');return Array.isArray(history)?history.filter(item=>item&&Number.isFinite(item.delta)&&typeof item.reason==='string').slice(0,100):[];}catch{return[];}}
function setXpBalance(balance,reason='XP balance update'){const previous=getXpBalance(),next=Math.max(0,Math.floor(Number(balance)||0));let lifetime=Number(localStorage.getItem('numoraLifetimeXP'));if(!Number.isSafeInteger(lifetime)||lifetime<0)lifetime=previous;if(next>previous)lifetime=Math.min(Number.MAX_SAFE_INTEGER,lifetime+next-previous);localStorage.setItem('numoraLifetimeXP',String(lifetime));localStorage.setItem('numoraXP',String(next));if(next!==previous){const history=readXpHistory();history.unshift({delta:next-previous,reason:String(reason).slice(0,80),at:new Date().toISOString()});localStorage.setItem('numoraXpHistory',JSON.stringify(history.slice(0,100)));}saveCurrentAccountProgress();return next;}
function xpHistoryMarkup(){const spanish=localStorage.getItem('numoraLanguage')==='es',history=readXpHistory();return `<section class="xp-history" aria-labelledby="xp-history-title"><h3 id="xp-history-title">${spanish?'Actividad de XP':'XP activity'}</h3>${history.length?`<ul>${history.slice(0,8).map(item=>`<li><span><strong>${escapeHtmlText(item.reason)}</strong><small>${new Date(item.at).toLocaleString(spanish?'es':'en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></span><b class="${item.delta>0?'xp-history-earned':'xp-history-spent'}">${item.delta>0?'+':''}${item.delta} XP</b></li>`).join('')}</ul>`:`<p>${spanish?'Tus ganancias y compras de XP aparecerán aquí.':'Your XP earnings and purchases will show here.'}</p>`}</section>`;}
