function lessonTopicDescription(title){const lesson=String(title||'').toLowerCase();const topics=[[/count|number line/,'count, read, and place numbers'],[/shape|geometry|symmetr|triangle|angle|circle|transform|conic/,'recognize shapes and use their geometric properties'],[/big and small|compare|greater|less|rational|real number/,'compare values and explain which is greater'],[/pattern|sequence|series/,'spot a rule and use it to predict what comes next'],[/sort|color|group/,'sort objects into groups and compare the groups'],[/addition|add |add&|add &|sum|number bond/,'add numbers using a strategy that fits the problem'],[/subtraction|subtract|difference/,'subtract numbers and check the result'],[/place value|tens and ones|hundreds/,'understand how a digit’s position changes its value'],[/time|elapsed/,'read clocks and solve time questions'],[/fraction|mixed number/,'represent, compare, and calculate with fractions'],[/measure|length|unit conversion/,'measure quantities and use the right units'],[/money|financial|interest/,'solve problems using money and financial math'],[/word problem|story|problem solving/,'turn a written situation into a math problem'],[/graph|chart|data display|plot|scatter/,'read and interpret information shown in graphs'],[/multiplication|multiply|array|equal groups/,'multiply using groups, arrays, and place value'],[/division|divide/,'divide into equal groups and interpret quotients'],[/area|surface|volume/,'find area, surface area, or volume'],[/perimeter|circumference/,'measure the distance around shapes'],[/decimal|hundredth|tenths/,'read and calculate with decimal place value'],[/factor|multiple|prime/,'use factors and multiples to describe number relationships'],[/coordinate|grid/,'locate and describe points on a coordinate grid'],[/ratio|rate|proportion/,'compare quantities with ratios, rates, and proportions'],[/percent|discount/,'connect percents to fractions and solve percent problems'],[/equation|inequal|expression/,'write or solve equations and inequalities'],[/probability|sampling|expected value/,'describe likelihood and analyze possible outcomes'],[/function|linear/,'connect inputs and outputs using functions'],[/exponent|power|scientific notation/,'use exponents to represent repeated multiplication'],[/logarithm/,'use logarithms to find unknown exponents'],[/derivative|differential|optimization/,'study how functions change and apply derivatives'],[/integral|calculus|limit/,'use limits and integrals to analyze change and accumulated area'],[/vector|matrix|linear algebra/,'work with vectors and organize values in matrices'],[/statistics|inference|regression/,'summarize data and draw conclusions from it'],[/proof|congruence|similarity/,'justify geometric relationships with clear reasoning'],[/trigonometry|sine|cosine/,'use angle and side relationships in triangles'],[/real number/,'classify numbers and reason about their values']];const match=topics.find(([pattern])=>pattern.test(lesson));return `Learn how to ${match?match[1]:'understand this topic and use it to solve problems'}.`;}
function librarySkills(grade=selectedGrade){const names=gradeSkillNames[grade]||gradeSkillNames['Grade 6'];const finished=new Set(badgeProgress.finishedLessons||[]);return names.map((title,index)=>{const template=skills[index%skills.length];return{...template,title,desc:`${grade} · 10 questions`,objective:lessonTopicDescription(title),finished:finished.has(lessonKey(grade,title)),grade,order:index};});}
