function saveMistakeNotebook(items){localStorage.setItem('numoraMistakes',JSON.stringify(items.slice(0,100)));saveCurrentAccountProgress();syncProfile();}
function recordPracticeMistake(wrongAnswer){if(!currentQuestion||!activeLesson)return;const prompt=String(currentQuestion.prompt||document.querySelector('.question-card h1')?.textContent||'').trim();const id=lessonKey(selectedGrade,activeLesson)+'|'+prompt;const mistakes=readMistakeNotebook();const prior=mistakes.find(item=>item.id===id);const entry={id,grade:selectedGrade,lesson:activeLesson,prompt,wrongAnswer:String(wrongAnswer||'').slice(0,120),correctAnswer:String(currentQuestion.answer??''),explanation:String(currentQuestion.explanation||''),missedAt:new Date().toISOString(),attempts:(Number(prior?.attempts)||0)+1,reviewStage:0,reviewDueAt:Date.now()};if(prior)Object.assign(prior,entry);else mistakes.unshift(entry);saveMistakeNotebook(mistakes);}
function mistakesView(){pageTitle.textContent='Mistake notebook';const mistakes=readMistakeNotebook();content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">LEARN FROM EACH TRY</span><h1>Mistake notebook</h1><p>Questions you missed are saved privately to this account so you can revisit them.</p></div></div>${mistakes.length?`<label class="notes-search-label" for="mistake-search">Find a missed question</label><input class="notes-search" id="mistake-search" type="search" placeholder="Search lesson or question…" autocomplete="off"><div class="mistake-list">${mistakes.map(item=>`<article class="card mistake-card"><div class="mistake-heading"><span class="skill-tag">${escapeHtmlText(item.grade)} · ${escapeHtmlText(item.lesson)}</span><small>Last tried ${new Date(item.missedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${item.attempts||1} ${Number(item.attempts)===1?'try':'tries'}</small></div><h2>${escapeHtmlText(item.prompt)}</h2><p>You entered <strong>${escapeHtmlText(item.wrongAnswer)}</strong>. The correct answer is <strong>${escapeHtmlText(item.correctAnswer)}</strong>.</p>${item.explanation?`<div class="mistake-explanation">${escapeHtmlText(item.explanation).replace(/&lt;br\s*\/?&gt;/gi,' ')}</div>`:''}<div class="mistake-actions"><button class="primary-btn" data-action="review-mistake" data-grade="${escapeHtmlText(item.grade)}" data-lesson="${escapeHtmlText(item.lesson)}">Practice this lesson</button><button class="secondary-btn" data-action="clear-mistake" data-mistake-id="${encodeURIComponent(item.id)}">I’ve got it now</button></div></article>`).join('')}</div><p class="notes-empty hidden" data-mistake-empty role="status">No missed questions match that search.</p>`:'<section class="card empty-state"><div style="font-size:46px">📓</div><h2>Your notebook is empty</h2><p>If an answer is incorrect, Numora will save the question here for another look.</p><button class="primary-btn" data-practice="${escapeHtmlText(resumeLessonName())}">Start practicing</button></section>'}</div>`;}let flashcardQueue=[],flashcardDone=0,flashcardRevealed=false,flashcardAllMode=false;
function flashcardsView(showAll=false){pageTitle.textContent='Flashcard review';flashcardAllMode=showAll;const now=Date.now();flashcardQueue=readMistakeNotebook().filter(item=>showAll||!Number(item.reviewDueAt)||Number(item.reviewDueAt)<=now).sort((a,b)=>(Number(a.reviewDueAt)||0)-(Number(b.reviewDueAt)||0)).map(item=>item.id);flashcardDone=0;flashcardRevealed=false;renderFlashcard();}
function scheduleFlashcard(id,stage,delay){const all=readMistakeNotebook();const item=all.find(card=>card.id===id);if(!item)return;item.reviewStage=stage;item.reviewDueAt=Date.now()+delay;saveMistakeNotebook(all);}
function renderFlashcard(){const all=readMistakeNotebook(),spanish=localStorage.getItem('numoraLanguage')==='es';if(!flashcardQueue.length){const due=all.filter(item=>!Number(item.reviewDueAt)||Number(item.reviewDueAt)<=Date.now()).length;const nextDue=all.reduce((soonest,item)=>{const value=Number(item.reviewDueAt)||0;return value>0&&(soonest===0||value<soonest)?value:soonest;},0);const title=flashcardDone?'Review complete!':all.length&&!due?'All caught up for now':'No cards to review yet';const message=flashcardDone?(spanish?`Marcaste ${flashcardDone} ${flashcardDone===1?'tarjeta':'tarjetas'} para repasarlas después. Tu calendario quedó guardado.`:`You marked ${flashcardDone} ${flashcardDone===1?'card':'cards'} for a future review. Your schedule is saved.`):all.length&&!due?(spanish?`Tu próxima tarjeta toca ${nextDue?new Date(nextDue).toLocaleString():'más tarde'}. También puedes repasarlas todas ahora.`:`Your next card is due ${nextDue?new Date(nextDue).toLocaleString():'later'}. You can still review everything now.`):'Questions you miss will appear here so you can study them later.';content.innerHTML=`<div class="page-wrap"><section class="card empty-state flashcard-finish"><div style="font-size:48px">${flashcardDone?'🎉':all.length?'🌿':'🧠'}</div><h1>${title}</h1><p>${message}</p>${all.length?`<button type="button" class="primary-btn" data-flashcard-action="${flashcardAllMode?'restart':'all'}">${spanish?(flashcardAllMode?'Repasar todas las tarjetas otra vez':'Repasar todas las tarjetas'):(flashcardAllMode?'Review all cards again':'Review all cards')}</button>`:'<button type="button" class="primary-btn" data-view="mistakes">Open Mistake notebook</button>'}</section></div>`;return;}const item=all.find(card=>card.id===flashcardQueue[0]);if(!item){flashcardQueue.shift();renderFlashcard();return;}const total=flashcardDone+flashcardQueue.length;content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">MISTAKE NOTEBOOK</span><h1>Flashcard review</h1><p>${spanish?(flashcardAllMode?'Primero las tarjetas pendientes · repasando todas las tarjetas guardadas':'Primero las tarjetas pendientes · repasando las que tocan hoy'):(flashcardAllMode?'Due cards first · reviewing all saved cards':'Due cards first · reviewing cards due now')}</p></div><button type="button" class="secondary-btn" data-view="mistakes">Back to mistakes</button></div><section class="card flashcard-review-card"><div class="flashcard-meta"><span>${escapeHtmlText(item.grade)} · ${escapeHtmlText(item.lesson)}</span><strong>${Math.min(flashcardDone+1,total)} of ${total}</strong></div><h2>${escapeHtmlText(item.prompt)}</h2>${flashcardRevealed?`<div class="flashcard-answer"><span>Correct answer</span><strong>${escapeHtmlText(item.correctAnswer)}</strong>${item.explanation?`<p>${escapeHtmlText(item.explanation).replace(/&lt;br\s*\/?&gt;/gi,' ')}</p>`:''}</div>`:'<p class="flashcard-prompt">Solve it in your head or on paper, then reveal the answer.</p>'}<div class="flashcard-actions">${flashcardRevealed?`<button type="button" class="secondary-btn" data-flashcard-action="again">${spanish?'Todavía estoy aprendiendo · repasar otra vez':'Still learning · review again'}</button><button type="button" class="primary-btn" data-flashcard-action="known">Got it</button>`:'<button type="button" class="primary-btn" data-flashcard-action="reveal">Reveal answer</button>'}</div></section></div>`;}
document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-flashcard-action]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();const action=button.dataset.flashcardAction;if(action==='all'){flashcardsView(true);return;}if(action==='restart'){flashcardsView(flashcardAllMode);return;}if(action==='reveal'){flashcardRevealed=true;}else if(action==='again'){const current=flashcardQueue.shift();if(current){scheduleFlashcard(current,0,10*60*1000);flashcardQueue.push(current);}flashcardRevealed=false;}else if(action==='known'){const current=flashcardQueue.shift();if(current){const card=readMistakeNotebook().find(item=>item.id===current);const stage=Math.min((Number(card?.reviewStage)||0)+1,5);const intervals=[1,3,7,14,30];scheduleFlashcard(current,stage,intervals[stage-1]*24*60*60*1000);flashcardDone++;}flashcardRevealed=false;}renderFlashcard();},true);function notesView(){pageTitle.textContent='My notes';const entries=Object.entries(readLessonNotes()).filter(([,note])=>typeof note==='string'&&note.trim()).map(([key,note])=>{const split=key.indexOf('|');return{grade:split<0?selectedGrade:key.slice(0,split),lesson:split<0?key:key.slice(split+1),note};}).sort((a,b)=>a.grade.localeCompare(b.grade)||a.lesson.localeCompare(b.lesson));content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">YOUR STUDY NOTEBOOK</span><h1>My notes</h1><p>Your lesson notes are saved to this account on this device.</p></div>${entries.length?'<button class="secondary-btn" data-action="export-lesson-notes">Download notes</button>':''}</div>${entries.length?`<label class="notes-search-label" for="notes-search">Find a note</label><input class="notes-search" id="notes-search" type="search" placeholder="Search lessons or note text…" autocomplete="off"><div class="lesson-notes-list">${entries.map(item=>`<article class="card lesson-note-card"><div><span class="report-kicker">${escapeHtmlText(item.grade)}</span><h2>${escapeHtmlText(item.lesson)}</h2></div><p>${escapeHtmlText(item.note)}</p><button type="button" class="secondary-btn" data-action="open-lesson-note" data-grade="${escapeHtmlText(item.grade)}" data-lesson="${escapeHtmlText(item.lesson)}">Open lesson →</button></article>`).join('')}</div><p class="notes-empty hidden" role="status">No notes match that search.</p>`:'<section class="card empty-state"><div style="font-size:46px">📝</div><h2>No lesson notes yet</h2><p>Write a note during practice and it will appear here. You can download a copy whenever you like.</p><button class="primary-btn" data-practice="${escapeHtmlText(resumeLessonName())}">Start practicing</button></section>'}</div>`;}
function savedSkillCard(s,grade=s.grade||selectedGrade){const key=lessonKey(grade,s.title);const finished=(badgeProgress.finishedLessons||[]).includes(key);const savedCount=finished?10:savedLessonQuestionCount(grade,s.title);const progress=finished?100:savedCount*10;const encoded=encodeURIComponent(key);return `<article class="skill-card ${finished?'skill-finished':''} saved-skill-card" data-practice="lesson" data-lesson="${s.title}" data-grade="${grade}"><div class="skill-top"><span class="skill-icon">${finished?'✓':s.icon}</span><button type="button" class="skill-save-button saved" data-toggle-saved-skill="${encoded}" aria-label="Remove ${s.title} from saved skills" title="Remove from saved skills">★</button><span class="level ${finished?'finished':''}">${finished?'✓ Finished':savedCount?`${savedCount}/10`:'Not started'}</span></div><h3>${s.title}</h3><p>${grade}${finished?` · ${formatCompletionTime(badgeProgress.finishedAt?.[key])||'Finished'}`:savedCount?` · ${savedCount} of 10 questions done`:' · Saved for later'}</p><div class="tiny-progress"><span style="width:${progress}%;background:${finished?'var(--mint)':s.color}"></span></div><button type="button" class="secondary-btn saved-practice-btn" data-action="practice-saved-skill" data-lesson="${escapeHtmlText(s.title)}" data-grade="${escapeHtmlText(grade)}">${finished?'Review lesson →':'Practice now →'}</button></article>`;}
function lessonKey(grade=selectedGrade,lesson=''){return `${grade}|${lesson}`;}
function formatCompletionTime(value){if(!value)return '';const date=new Date(value);if(!Number.isFinite(date.getTime()))return '';return `Finished ${date.toLocaleDateString(undefined,{month:'short',day:'numeric'})} at ${date.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}`;}
function savedLessonQuestionCount(grade,lesson){const key=lessonKey(grade,lesson);let count=Math.min(10,Math.max(0,Number(badgeProgress.lessonProgress?.[key])||0));const paused=savedPausedLesson();if(paused?.lesson===lesson&&grade===selectedGrade)count=Math.max(count,Math.min(10,Math.max(0,Number(paused.question)||0)));return count;}
function lessonIndexKey(){return 'numoraLessonIndex_'+selectedGrade;}
function savedLessonIndex(){return Number(localStorage.getItem(lessonIndexKey())||0);}
function pausedLessonKey(){return 'numoraPausedLesson_'+selectedGrade;}
function savedPausedLesson(){try{return JSON.parse(localStorage.getItem(pausedLessonKey())||'null');}catch{return null;}}
function savePausedLesson(){if(activeLesson)localStorage.setItem(pausedLessonKey(),JSON.stringify({lesson:activeLesson,index:activeLessonIndex,question:lessonQuestionCount}));}
function clearPausedLesson(){localStorage.removeItem(pausedLessonKey());}
function resumeLessonName(){const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const paused=savedPausedLesson();return paused&&names.includes(paused.lesson)?paused.lesson:names[Math.min(savedLessonIndex(),names.length-1)];}
function showLessonComplete(){lessonQuestionCount=lessonQuestionLimit;window.currentLessonQuestionCount=lessonQuestionLimit;updateBadgeProgress(activeLesson,true);saveCurrentAccountProgress();const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const nextIndex=Math.min(activeLessonIndex+1,names.length-1);localStorage.setItem(lessonIndexKey(),String(nextIndex));clearPausedLesson();const celebration=localStorage.getItem('numoraLessonCelebrations')!=='false';const celebrationMarkup=celebration?'<div class="lesson-celebration" aria-hidden="true"><span>🎉</span><span>⭐</span><span>✨</span><span>🎊</span><span>🌟</span><span>🎈</span></div>':'';content.innerHTML=`<div class="page-wrap"><section class="card empty-state lesson-finish-card">${celebrationMarkup}<div class="lesson-finish-icon">🎉</div><h2>Good job! You finished the lesson.</h2><p>You completed ${lessonQuestionLimit} questions in <strong>${escapeHtmlText(activeLesson)}</strong>.</p><p class="finish-xp-balance">Your XP balance: <strong>${getXpBalance()} XP</strong></p><div class="lesson-finish-actions">${activeLessonIndex<names.length-1?`<button class="primary-btn next-lesson-btn">Go to next lesson: ${escapeHtmlText(names[nextIndex])} →</button>`:'<p>You finished every lesson in this level!</p>'}<button type="button" class="secondary-btn" data-replay-lesson="${escapeHtmlText(activeLesson)}">Practice this lesson again</button><button type="button" class="secondary-btn" data-share-lesson-win>Share your win</button><button type="button" class="text-link" data-view="home">Back to my learning</button></div></section></div>`;lessonQuestionLimit=10;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-share-lesson-win]');if(!button)return;const spanish=localStorage.getItem('numoraLanguage')==='es';const message=spanish?`¡Terminé “${activeLesson}” en ${selectedGrade} con Numora!`:`I finished “${activeLesson}” in ${selectedGrade} on Numora!`;const shareUrl=new URL(location.href);shareUrl.search='';shareUrl.searchParams.set('win',activeLesson);shareUrl.searchParams.set('grade',selectedGrade);try{if(navigator.share){await navigator.share({title:spanish?'¡Lección terminada!':'Lesson complete!',text:message,url:shareUrl.href});}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(message+' '+shareUrl.href);showToast(spanish?'Tu logro se copió al portapapeles.':'Your lesson win was copied to the clipboard.');}else{const field=document.createElement('textarea');field.value=message+' '+shareUrl.href;document.body.appendChild(field);field.select();document.execCommand('copy');field.remove();showToast(spanish?'Tu logro se copió al portapapeles.':'Your lesson win was copied to the clipboard.');}}catch(error){if(error?.name!=='AbortError')showToast(spanish?'No se pudo compartir ahora.':'Could not share right now.');}});

