function skillCard(s){const grade=s.grade||selectedGrade;const key=lessonKey(grade,s.title);const savedCount=s.finished?10:savedLessonQuestionCount(grade,s.title);const shownProgress=s.finished?100:savedCount*10;const isNew=!s.finished&&savedCount===0;const status=s.finished?'✓ Finished':isNew?'Not started':`${savedCount}/10`;const detail=s.finished?(formatCompletionTime(badgeProgress.finishedAt?.[key])||'You finished this lesson!'):savedCount?`${savedCount} of 10 questions completed`:s.desc;const saved=readSavedSkills().includes(key);return `<article class="skill-card ${s.finished?'skill-finished':''}" data-practice="lesson" data-lesson="${s.title}" data-grade="${grade}" data-skill-key="${encodeURIComponent(key)}" data-progress="${savedCount}" data-order="${s.order??0}"><div class="skill-top"><span class="skill-icon">${s.finished?'✓':s.icon}</span><button type="button" class="skill-save-button ${saved?'saved':''}" data-toggle-saved-skill="${encodeURIComponent(key)}" aria-label="${saved?'Remove':'Save'} ${s.title} ${saved?'from':'to'} saved skills" title="${saved?'Remove from':'Save to'} saved skills">${saved?'★':'☆'}</button><span class="level ${s.finished?'finished':''} ${isNew?'new-skill':''}">${status}</span></div><h3>${s.title}</h3><small class="lesson-objective">${s.objective||lessonTopicDescription(s.title)}</small><p>${detail}</p><div class="tiny-progress"><span style="width:${shownProgress}%;background:${s.finished?'var(--mint)':s.color}"></span></div></article>`}
function skillsView(){pageTitle.textContent='Skill library';const lessonCount=gradeLessonCounts[selectedGrade]||24;content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">${selectedGrade} Explorer</span><h1>Find your next win</h1><p>Search lessons or filter your collection to find what to practice next.</p></div><button class="secondary-btn">${selectedGrade} ⌄</button></div><div class="section-heading"><h2>${selectedGrade} Math · ${lessonCount} lessons</h2><button type="button" class="primary-btn" data-pick-random-skill>Pick for me ✨</button></div><div class="skill-library-tools"><label class="skill-search-label" for="skill-search">Search skills</label><input id="skill-search" type="search" placeholder="Try fractions, shapes, patterns…" autocomplete="off"><select id="skill-filter" aria-label="Filter skills"><option value="all">All skills</option><option value="unfinished">Not finished</option><option value="in-progress">In progress</option><option value="not-started">Not started</option><option value="needs-practice">Needs practice</option><option value="finished">Finished</option><option value="saved">Saved</option></select><select id="skill-sort" aria-label="Sort lessons"><option value="recommended">Recommended</option><option value="name">Name A to Z</option><option value="progress-high">Most progress</option><option value="progress-low">Least progress</option></select></div><div class="skill-grid skill-library-grid">${librarySkills().map(skillCard).join('')}</div><p class="skill-empty hidden" role="status">No matching skills. Try another search or filter.</p></div>`}
function savedSkillsView(){pageTitle.textContent='Saved skills';const saved=new Set(readSavedSkills());const cards=[];Object.entries(gradeSkillNames).forEach(([grade,names])=>names.forEach((title,index)=>{if(!saved.has(lessonKey(grade,title)))return;const template=skills[index%skills.length];cards.push(savedSkillCard({...template,title,grade},grade));}));content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">YOUR SHORTLIST</span><h1>Saved skills</h1><p>Keep lessons you want to practice again in one place.</p></div><div class="saved-skill-actions"><button type="button" class="secondary-btn" data-action="practice-random-saved">🎲 Practice a saved skill</button><button class="text-link" data-view="skills">Browse all skills →</button></div></div>${cards.length?`<div class="skill-grid skill-library-grid">${cards.join('')}</div>`:'<section class="card empty-state saved-empty"><div style="font-size:42px">☆</div><h2>No saved skills yet</h2><p>Tap the star on any lesson card to add it here.</p><button class="primary-btn" data-view="skills">Explore skills</button></section>'}</div>`;}
function filterSkillLibrary(){const query=(document.querySelector('#skill-search')?.value||'').trim().toLocaleLowerCase();const filter=document.querySelector('#skill-filter')?.value||'all';const sort=document.querySelector('#skill-sort')?.value||'recommended';const saved=new Set(readSavedSkills());const needsPractice=new Set(readMistakeNotebook().map(item=>lessonKey(item.grade,item.lesson)));const grid=document.querySelector('.skill-library-grid');const cards=grid?[...grid.querySelectorAll('.skill-card')]:[];cards.sort((a,b)=>sort==='name'?a.querySelector('h3').textContent.localeCompare(b.querySelector('h3').textContent):sort==='progress-high'?Number(b.dataset.progress)-Number(a.dataset.progress):sort==='progress-low'?Number(a.dataset.progress)-Number(b.dataset.progress):Number(a.dataset.order)-Number(b.dataset.order));let visible=0;cards.forEach(card=>{const matchesText=card.querySelector('h3')?.textContent.toLocaleLowerCase().includes(query);const finished=card.classList.contains('skill-finished');const progress=Number(card.dataset.progress||0);const key=decodeURIComponent(card.dataset.skillKey||'');const matchesFilter=filter==='all'||(filter==='finished'?finished:filter==='unfinished'?!finished:filter==='in-progress'?progress>0&&!finished:filter==='not-started'?progress===0&&!finished:filter==='needs-practice'?needsPractice.has(key):saved.has(key));const show=matchesText&&matchesFilter;card.classList.toggle('hidden',!show);if(show)visible++;grid.appendChild(card);});document.querySelector('.skill-empty')?.classList.toggle('hidden',visible>0);}
