    {id:'lesson',icon:'📘',title:es?'Practica tu lección actual':'Practice your current lesson',detail:es?`Continúa ${escapeHtmlText(lesson)} en Matemáticas de ${escapeHtmlText(selectedGrade)}.`:`Pick up ${escapeHtmlText(lesson)} in ${escapeHtmlText(selectedGrade)} Math.`,action:`<button class="primary-btn" data-practice="${escapeHtmlText(lesson)}">${savedPausedLesson()?.lesson===lesson?(es?'Continuar lección':'Continue lesson'):(es?'Empezar lección':'Start lesson')} →</button>`},
    {id:'goal',icon:'🎯',title:left?(es?`Responde ${left} ${left===1?'pregunta más':'preguntas más'}`:`Answer ${left} more ${left===1?'question':'questions'}`):(es?'¡Meta diaria cumplida!':'Daily goal complete!'),detail:left?(es?`Alcanza tu meta diaria de ${target} preguntas.`:`Reach your ${target}-question daily goal.`):(es?'Alcanzaste tu meta de preguntas. ¡Buen trabajo!':'You reached your question goal. Nice work!'),action:`<button class="secondary-btn" data-view="goals">${left?(es?'Ver meta diaria':'View daily goal'):(es?'Ver meta':'See goal')} →</button>`}
