let challengeTimer=0,challengePaused=false,challengeScore=0,challengeQuestion=0,challengeAnswered=0,challengeSkipped=0,challengeAnswer=0,challengeStreak=0,challengeBestStreak=0,challengeTimeRemaining=60,challengeDuration=60,challengeMode='mixed',challengeDifficulty='standard',lessonQuestionLimit=10;
function challengeModeName(mode){return mode==='mixed'?'Mixed operations':mode==='addition'?'Addition':mode==='subtraction'?'Subtraction':mode==='division'?'Division':'Multiplication';}
function challengeDifficultyName(level){return level==='warmup'?'Warm-up':level==='stretch'?'Brain stretch':'Standard';}
function readChallengeHistory(){try{const history=JSON.parse(localStorage.getItem('numoraChallengeHistory')||'[]');return Array.isArray(history)?history.filter(item=>item&&Number.isFinite(Number(item.score))).slice(0,5):[];}catch{return[];}}
function challengeView(){pageTitle.textContent='Timed challenge';const history=readChallengeHistory();content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">Math sprint</span><h1>Timed challenge</h1><p>Choose a pace and math mode, then answer as many questions as you can.</p></div></div><section class="card empty-state"><div style="font-size:50px">⏱</div><h2>Ready for a quick challenge?</h2><p>Correct answers earn 10 XP. Keep a 5-answer streak for a 25 XP bonus!</p><div class="challenge-records" aria-label="Your challenge records"><div><strong>${Number(localStorage.getItem("numoraBestChallenge")||0)}</strong><small>Best score</small></div><div><strong>${Number(localStorage.getItem("numoraBestChallengeStreak")||0)}</strong><small>Longest streak</small></div></div><div class="challenge-choices"><label>Time limit<select id="challenge-duration"><option value="30">30 seconds</option><option value="60" selected>60 seconds</option><option value="90">90 seconds</option><option value="120">2 minutes</option><option value="180">3 minutes</option></select></label><label>Math mode<select id="challenge-mode"><option value="mixed">Mixed operations</option><option value="addition">Addition</option><option value="subtraction">Subtraction</option><option value="multiplication">Multiplication</option><option value="division">Division</option></select></label><label>Difficulty<select id="challenge-difficulty"><option value="warmup">Warm-up</option><option value="standard" selected>Standard</option><option value="stretch">Brain stretch</option></select></label></div><button class="primary-btn" data-action="start-challenge">Start challenge →</button></section>${history.length?`<section class="card challenge-history"><h2>Recent runs</h2>${history.map(item=>`<div class="challenge-history-row"><span>${escapeHtmlText(challengeModeName(item.mode))} · ${escapeHtmlText(challengeDifficultyName(item.difficulty||"standard"))} · ${item.duration}s</span><strong>${item.score} correct · ${item.attempted?Math.round(item.score/item.attempted*100):0}% · ${item.bestStreak||0} best streak · ${item.skipped||0} skipped</strong><small>${new Date(item.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small><button type="button" class="secondary-btn challenge-replay-btn" data-action="replay-challenge" data-duration="${Number(item.duration)||60}" data-mode="${escapeHtmlText(item.mode||'mixed')}" data-difficulty="${escapeHtmlText(item.difficulty||'standard')}">Replay</button></div>`).join('')}</section>`:''}</div>`;}
function renderChallengeQuestion(){const minimum=challengeDifficulty==='stretch'?10:1;const maximum=challengeDifficulty==='warmup'?10:challengeDifficulty==='stretch'?99:20;let a=Math.floor(Math.random()*(maximum-minimum+1))+minimum,b=Math.floor(Math.random()*(maximum-minimum+1))+minimum,operator='+';if(challengeMode==='division'){b=Math.floor(Math.random()*11)+2;a=b*(Math.floor(Math.random()*(maximum-minimum+1))+minimum);operator='÷';}else if(challengeMode==='multiplication'||(challengeMode==='mixed'&&Math.random()<.25)){operator='×';b=Math.floor(Math.random()*11)+2;}else if(challengeMode==='subtraction'||(challengeMode==='mixed'&&Math.random()<.333)){operator='−';}if(operator==='−'&&b>a)[a,b]=[b,a];challengeAnswer=operator==='+'?a+b:operator==='−'?a-b:operator==='×'?a*b:a/b;const prompt=`What is ${a} ${operator} ${b}?`;content.innerHTML=`<div class="practice-shell"><button class="back" data-view="home">← Back to my learning</button><div class="practice-meta"><span><b>TIMED CHALLENGE · ${escapeHtmlText(challengeModeName(challengeMode))} · ${escapeHtmlText(challengeDifficultyName(challengeDifficulty))}</b></span><span><strong data-challenge-time>${challengeTimeRemaining}</strong>s · ${challengeScore} correct · ${challengeStreak} streak</span></div><div class="progress-line"><span style="width:${Math.min(100,challengeQuestion*10)}%"></span></div><section class="question-card"><span class="skill-tag">QUESTION ${challengeQuestion+1}</span><h1>${prompt}</h1><input class="answer-input" inputmode="numeric" aria-label="Challenge answer" autofocus><div class="feedback"></div><div class="practice-controls"><button class="primary-btn" data-action="submit-challenge">Check answer</button><button type="button" class="secondary-btn" data-action="skip-challenge">Skip question →</button><button type="button" class="secondary-btn" data-action="toggle-challenge-pause" aria-pressed="false">Pause timer</button></div></section></div>`;document.querySelector('.answer-input')?.focus();}
function startChallenge(options={}){clearInterval(challengeTimer);challengePaused=false;challengeScore=0;challengeQuestion=0;challengeAnswered=0;challengeSkipped=0;challengeStreak=0;challengeBestStreak=0;challengeDuration=Number(options.duration??document.querySelector('#challenge-duration')?.value)||60;challengeTimeRemaining=challengeDuration;challengeMode=options.mode||document.querySelector('#challenge-mode')?.value||'mixed';challengeDifficulty=options.difficulty||document.querySelector('#challenge-difficulty')?.value||'standard';renderChallengeQuestion();challengeTimer=setInterval(()=>{if(challengePaused)return;challengeTimeRemaining--;const node=document.querySelector('[data-challenge-time]');if(node)node.textContent=String(challengeTimeRemaining);if(challengeTimeRemaining<=0)endChallenge();},1000);}
function endChallenge(){if(!challengeTimer)return;clearInterval(challengeTimer);challengeTimer=0;const previousBest=Number(localStorage.getItem('numoraBestChallenge')||0);const newRecord=challengeScore>previousBest;const previousStreak=Number(localStorage.getItem("numoraBestChallengeStreak")||0);const newStreakRecord=challengeBestStreak>previousStreak;localStorage.setItem("numoraBestChallengeStreak",String(Math.max(previousStreak,challengeBestStreak)));localStorage.setItem('numoraBestChallenge',String(Math.max(previousBest,challengeScore)));const attempted=challengeAnswered,accuracy=attempted?Math.round(challengeScore/attempted*100):0;const history=readChallengeHistory();history.unshift({score:challengeScore,attempted,accuracy,skipped:challengeSkipped,bestStreak:challengeBestStreak,duration:challengeDuration,mode:challengeMode,difficulty:challengeDifficulty,date:new Date().toISOString()});localStorage.setItem('numoraChallengeHistory',JSON.stringify(history.slice(0,5)));saveCurrentAccountProgress();content.innerHTML=`<div class="page-wrap"><section class="card empty-state"><div style="font-size:50px">🎉</div><h2>Challenge complete!</h2>${newRecord?'<p class="skill-tag">🏆 New personal best!</p>':''}<p>${newStreakRecord?"✨ New longest streak!":""}</p><p>You got <strong>${challengeScore}</strong> correct in ${challengeDuration} seconds. Accuracy: <strong>${attempted?accuracy+"%":"No answers yet"}</strong>. Skipped: <strong>${challengeSkipped}</strong>. Best answer streak: <strong>${challengeBestStreak}</strong>. Longest streak: <strong>${localStorage.getItem("numoraBestChallengeStreak")||challengeBestStreak}</strong>. Personal best: <strong>${localStorage.getItem('numoraBestChallenge')||challengeScore}</strong>.</p><button class="primary-btn" data-action="retry-challenge">Try same challenge again →</button><button type="button" class="secondary-btn" data-view="challenge">See recent runs</button></section></div>`;}
function customQuizView(){const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const rememberedLesson=localStorage.getItem('numoraCustomQuizLesson');const initialLesson=names.includes(rememberedLesson)?rememberedLesson:names[0];const count=['5','10','15','20'].includes(localStorage.getItem('numoraCustomQuizCount'))?localStorage.getItem('numoraCustomQuizCount'):'10';pageTitle.textContent='Custom quiz';content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">Make it yours</span><h1>Build a custom quiz</h1><p>Choose a lesson and how many questions you want to practice.</p></div></div><section class="card empty-state"><label for="custom-lesson">Lesson</label><select id="custom-lesson">${names.map(name=>`<option value="${escapeHtmlText(name)}" ${name===initialLesson?'selected':''}>${escapeHtmlText(name)}</option>`).join('')}</select><div class="custom-quiz-shortcuts"><button type="button" class="secondary-btn" data-action="custom-random-lesson">🎲 Pick random lesson</button><button type="button" class="secondary-btn" data-action="custom-next-lesson">⏭ Use next lesson</button></div><label for="custom-count">Questions</label><select id="custom-count">${[5,10,15,20].map(value=>`<option value="${value}" ${String(value)===count?'selected':''}>${value} questions</option>`).join('')}</select><p>Your lesson and quiz length are remembered for this account.</p><button type="button" class="primary-btn" onclick="window.startCustomQuiz()">Start custom quiz →</button></section></div>`;}
