window.startCustomQuiz=startCustomQuiz;
function simpleView(type){const data={reports:['Progress','Small steps, visible growth.','Your learning journey','You’ve answered 148 questions this month. Keep going to reach your 200-question milestone.'],badges:['Badges','Celebrate the milestones along the way.','Your collection','4 badges earned · 8 more to discover']}[type];pageTitle.textContent=data[0];content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">${data[0]}</span><h1>${data[1]}</h1><p>${data[3]}</p></div></div><section class="card empty-state"><div style="font-size:50px">${type==='badges'?'✹':'◒'}</div><h2>${data[2]}</h2><p>${data[3]}</p><button class="primary-btn" data-practice="${resumeLessonName()}">Start a practice set →</button></section></div>`}
function recentPracticeWeek(){const today=new Date(`${todayKey}T00:00:00Z`),practiced=new Set(badgeProgress.practiceDays||[]);return Array.from({length:7},(_,index)=>{const date=new Date(today);date.setUTCDate(date.getUTCDate()-(6-index));const key=date.toISOString().slice(0,10);return{key,label:date.toLocaleDateString(undefined,{weekday:'short',timeZone:'UTC'}),day:date.toLocaleDateString(undefined,{day:'numeric',timeZone:'UTC'}),practiced:practiced.has(key)};});}
function downloadProgressSummary(){const spanish=localStorage.getItem('numoraLanguage')==='es';const lessons=gradeSkillNames[selectedGrade]||[];const progress=lessons.map(title=>({title,count:savedLessonQuestionCount(selectedGrade,title)}));const finished=progress.filter(item=>item.count>=10).length;const started=progress.filter(item=>item.count>0&&item.count<10).length;const answered=progress.reduce((sum,item)=>sum+item.count,0);const percent=lessons.length?Math.round(answered/(lessons.length*10)*100):0;const inProgress=progress.filter(item=>item.count>0&&item.count<10).sort((a,b)=>b.count-a.count).map(item=>`• ${item.title} (${item.count}/10)`);const week=recentPracticeWeek();const activeDays=week.filter(day=>day.practiced).length;const due=readMistakeNotebook().filter(item=>!Number(item.reviewDueAt)||Number(item.reviewDueAt)<=Date.now()).length;const lines=spanish?['Resumen de progreso de Numora',`Fecha: ${new Date().toLocaleDateString()}`,`Grado: ${selectedGrade}`,`Progreso del grado: ${percent}%`,`Lecciones terminadas: ${finished} de ${lessons.length}`,`Lecciones en curso: ${started}`,`Preguntas respondidas en las lecciones: ${answered}`,`Preguntas completadas este mes: ${monthCompleted}`,`Días de práctica esta semana: ${activeDays} de 7`,`Racha actual: ${streak} días`,`Tarjetas pendientes: ${due}`,'','Lecciones en curso:',...(inProgress.length?inProgress:['• Ninguna por ahora'])]:['Numora Learning Progress Summary',`Date: ${new Date().toLocaleDateString()}`,`Grade: ${selectedGrade}`,`Grade progress: ${percent}%`,`Lessons finished: ${finished} of ${lessons.length}`,`Lessons in progress: ${started}`,`Questions answered in lessons: ${answered}`,`Questions completed this month: ${monthCompleted}`,`Practice days this week: ${activeDays} of 7`,`Current streak: ${streak} days`,`Flashcards due: ${due}`,'','Lessons in progress:',...(inProgress.length?inProgress:['• None yet'])];const file=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(file);link.download=spanish?'numora-resumen-de-progreso.txt':'numora-progress-summary.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);showToast(spanish?'Tu resumen de progreso está listo para descargar.':'Your progress summary is ready to download.');}function reportsView(){const monthName=new Date().toLocaleString(undefined,{month:'long'});const word=monthCompleted===1?'question':'questions';const days=recentPracticeWeek();const practicedDays=days.filter(day=>day.practiced).length;const lessons=gradeSkillNames[selectedGrade]||[];const lessonProgress=lessons.map(title=>({title,count:savedLessonQuestionCount(selectedGrade,title)}));const finishedLessons=lessonProgress.filter(item=>item.count>=10).length;const startedLessons=lessonProgress.filter(item=>item.count>0&&item.count<10).length;const answeredQuestions=lessonProgress.reduce((total,item)=>total+item.count,0);const gradePercent=lessons.length?Math.round(answeredQuestions/(lessons.length*10)*100):0;const currentLesson=lessonProgress.filter(item=>item.count>0&&item.count<10).sort((a,b)=>b.count-a.count)[0]?.title||resumeLessonName();const mistakeCount=readMistakeNotebook().length;pageTitle.textContent='Progress';content.innerHTML=`<div class="page-wrap"><div class="hero-row"><div><span class="eyebrow">Your learning journey</span><h1>${monthName} learning progress</h1><p>Your activity and practice history, all in one place.</p></div><button class="secondary-btn" data-action="export-progress-summary">Download my progress</button></div><div class="progress-report-grid"><section class="card month-progress-card"><span class="report-kicker">THIS MONTH</span><strong>${monthCompleted}</strong><h2>${word} completed</h2><p>Keep going and watch your progress grow.</p><button class="primary-btn" data-practice="${escapeHtmlText(resumeLessonName())}">Continue practice →</button></section><section class="card week-progress-card"><div class="week-card-heading"><div><span class="report-kicker">LAST 7 DAYS</span><h2>Practice calendar</h2></div><strong>${practicedDays}<small> / 7 days</small></strong></div><div class="practice-week">${days.map(day=>`<div class="practice-day ${day.practiced?'is-practiced':''}" aria-label="${day.label} ${day.day}: ${day.practiced?'practiced':'no practice'}"><span>${day.label}</span><b>${day.day}</b><i>${day.practiced?'✓':'·'}</i></div>`).join('')}</div><p>${streak?`You’re on a ${streak}-day streak. Keep it going!`:'Try a little practice today to start a new streak.'}</p></section></div><section class="card grade-mastery-card"><div class="grade-mastery-heading"><div><span class="report-kicker">${escapeHtmlText(selectedGrade.toUpperCase())} MATH</span><h2>Your grade progress</h2><p>Progress across the lessons in this grade.</p></div><strong>${gradePercent}%</strong></div><div class="grade-mastery-bar" role="progressbar" aria-label="Grade lesson progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${gradePercent}"><span style="width:${gradePercent}%"></span></div><div class="grade-mastery-stats"><div><strong>${finishedLessons} / ${lessons.length}</strong><small>Lessons finished</small></div><div><strong>${startedLessons}</strong><small>Lessons in progress</small></div><div><strong>${answeredQuestions}</strong><small>Questions answered</small></div></div><button class="secondary-btn" data-practice="${escapeHtmlText(currentLesson)}">Continue this lesson → <strong>${escapeHtmlText(currentLesson)}</strong></button></section><section class="card progress-footer-card"><div><span class="report-kicker">NEED ANOTHER LOOK?</span><h2>Practice questions to revisit</h2><p>${mistakeCount} ${mistakeCount===1?'question':'questions'} in your mistake notebook.</p></div><button class="secondary-btn" data-view="mistakes">Open mistake notebook →</button></section></div>`;}function practiceView(lessonOverride){const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const paused=savedPausedLesson();const pausedMatches=!lessonOverride||paused?.lesson===lessonOverride;let resumeComplete=false;if(pausedMatches&&paused&&names.includes(paused.lesson)){activeLessonIndex=Math.min(Math.max(0,Number(paused.index)||0),names.length-1);activeLesson=paused.lesson;const savedCount=Math.max(0,Number(paused.question)||0);resumeComplete=savedCount>=lessonQuestionLimit;lessonQuestionCount=Math.min(Math.max(0,lessonQuestionLimit-1),savedCount);}else{activeLessonIndex=lessonOverride?Math.max(0,names.indexOf(lessonOverride)):Math.min(savedLessonIndex(),names.length-1);activeLesson=lessonOverride||names[activeLessonIndex];lessonQuestionCount=0;}window.currentActiveLesson=activeLesson;window.currentLessonQuestionCount=lessonQuestionCount;savePausedLesson();freshStart=false;localStorage.setItem('numoraFreshStart','false');pageTitle.textContent='Practice';if(resumeComplete){showLessonComplete();return;}renderLessonQuestion();}
function goToNextLesson(){const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];if(activeLessonIndex<names.length-1){activeLessonIndex++;localStorage.setItem(lessonIndexKey(),String(activeLessonIndex));activeLesson=names[activeLessonIndex];window.currentActiveLesson=activeLesson;lessonQuestionCount=0;window.currentLessonQuestionCount=0;savePausedLesson();renderLessonQuestion();showToast('Next lesson: '+activeLesson);}else{clearPausedLesson();homeView();showToast('You completed every lesson in this level!');}}
window.practiceView=practiceView;
function newQuestion(){const lesson=activeLesson||window.currentActiveLesson||(gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'])[0];const isPreK=selectedGrade==='Pre-K';let a=isPreK?Math.floor(Math.random()*8)+1:Math.floor(Math.random()*7)+2;let b=isPreK?0:Math.floor(Math.random()*7)+1;currentQuestion={a,b,answer:isPreK?String(a+1):((a/10)+(b/10)).toFixed(1)};const prompt=isPreK?`What number comes after ${a}?`:`What is ${a/10} + ${b/10}?`;const explanation=isPreK?`Count forward one number: ${a}, then <b>${a+1}</b>.`:`Line up the decimal points, then add the tenths. ${a}/10 + ${b}/10 = ${(a+b)}/10, which is <b>${currentQuestion.answer}</b>.`;content.innerHTML=`<div class="practice-shell"><button class="back" data-view="home">← Back to my learning</button><div class="practice-meta"><span><b>${lesson.toUpperCase()}</b> · Practice</span><span>Question ${lessonQuestionCount+1} of ${lessonQuestionLimit}</span></div><div class="progress-line"><span style="width:${Math.min(100,lessonQuestionCount/lessonQuestionLimit*100)}%"></span></div><section class="question-card"><span class="skill-tag">${selectedGrade.toUpperCase()} · ${lesson.toUpperCase()}</span><h1>${prompt}</h1><input class="answer-input" inputmode="decimal" aria-label="Your answer" placeholder="Answer" autofocus /><div class="feedback"></div><div class="explain"><strong>Here’s the idea:</strong><br/>${explanation}</div><div class="practice-controls"><button class="secondary-btn explain-btn">Show explanation</button><button class="primary-btn check-btn">Check answer</button></div></section></div>`;bindPractice();if(localStorage.getItem('numoraAutoFocusAnswer')==='true'){const answer=document.querySelector('.answer-input');if(answer&&!answer.readOnly)requestAnimationFrame(()=>answer.focus());}}
function bindPractice(){const questionCard=document.querySelector('.question-card');const video=document.createElement('section');video.className='lesson-video';video.innerHTML='<div class="video-art"><span class="video-shape">＋</span><button class="video-play" aria-label="Play lesson video">▶</button></div><div class="video-copy"><strong>Watch: Adding decimals</strong><small>See a real example step by step · 2:14</small><div class="video-example">0.3 + 0.4 <b>= 0.7</b><em>3 tenths + 4 tenths = 7 tenths</em></div></div><span class="video-label">EXAMPLE LESSON</span>';questionCard.parentNode.insertBefore(video,questionCard);video.querySelector('.video-play').onclick=()=>{video.querySelector('.video-play').textContent='❚❚';video.classList.add('playing');showToast('Example video playing');};const tools=document.createElement('section');tools.className='tools-panel';tools.innerHTML='<div class="tools-title"><span>🧰 <strong>Tools</strong></span><small>Work it out here</small></div><div class="scratchpad"><div class="tool-label">Scratchpad</div><textarea placeholder="Write your steps here..."></textarea><small>Show your work before you submit.</small></div>';questionCard.parentNode.insertBefore(tools,questionCard);const input=document.querySelector('.answer-input'),feedback=document.querySelector('.feedback');input.readOnly=localStorage.getItem('numoraClickToTypeAnswer')==='false';input.setAttribute('aria-readonly',String(input.readOnly));if(input.readOnly)input.placeholder='Typing is off in Settings';document.querySelector('.check-btn').onclick=()=>{if(input.value.trim()==='')return;accuracyAttempts=Number(localStorage.getItem('numoraAccuracyAttempts')||0)+1;localStorage.setItem('numoraAccuracyAttempts',String(accuracyAttempts));const entered=input.value.trim().toLowerCase(),expected=String(currentQuestion.answer).trim().toLowerCase();const numericEntered=Number(entered),numericExpected=Number(expected);let ok=Number.isFinite(numericEntered)&&Number.isFinite(numericExpected)?Math.abs(numericEntered-numericExpected)<.001:entered===expected;input.className='answer-input '+(ok?'correct':'wrong');feedback.className='feedback '+(ok?'success':'error');feedback.textContent=ok?'Nice work! That’s correct. ✦':'Not quite — try once more or peek at the explanation.';if(ok){accuracyCorrect=Number(localStorage.getItem('numoraAccuracyCorrect')||0)+1;localStorage.setItem('numoraAccuracyCorrect',String(accuracyCorrect));completed++;localStorage.setItem('numoraCompleted',String(completed));document.querySelector('.check-btn').textContent='Next question →';document.querySelector('.check-btn').onclick=newQuestion;showToast('Question complete · +10 XP');}};document.querySelector('.explain-btn').onclick=()=>document.querySelector('.explain').classList.toggle('show');input.addEventListener('keydown',e=>{if(e.key==='Enter')document.querySelector('.check-btn').click()})}
const safeLessonVideoObserver=new MutationObserver(()=>{const title=document.querySelector('.lesson-video .video-copy strong');const example=document.querySelector('.lesson-video .video-example');if(!title||!example||!currentQuestion)return;const signature=selectedGrade+'-'+currentQuestion.a+'-'+currentQuestion.b+'-'+currentQuestion.answer;if(example.dataset.signature===signature)return;example.dataset.signature=signature;const lesson=activeLesson||window.currentActiveLesson||(gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'])[0];title.textContent='Watch: '+selectedGrade+' Math · '+lesson;if(selectedGrade==='Pre-K'){example.innerHTML='<span>Step 1: Start at '+currentQuestion.a+'.</span><span>Step 2: Count one more number.</span><span>Step 3: '+currentQuestion.a+' comes before <b>'+currentQuestion.answer+'</b>.</span>';}else{const total=(currentQuestion.a+currentQuestion.b)/10;example.innerHTML='<span>Step 1: Line up the decimal points.</span><span>Step 2: Add '+currentQuestion.a+' tenths + '+currentQuestion.b+' tenths = '+(currentQuestion.a+currentQuestion.b)+' tenths.</span><span>Step 3: Write the answer: <b>'+total.toFixed(1)+'</b>.</span>';}});safeLessonVideoObserver.observe(content,{childList:true,subtree:true});
const demoVideoObserver=new MutationObserver(()=>{const example=document.querySelector('.lesson-video .video-example');if(!example||example.dataset.demo==='true')return;example.dataset.demo='true';if(selectedGrade==='Pre-K'){example.innerHTML='<span>Example: What comes after 8?</span><span>Count one more number: 9.</span><span><b>8 comes before 9.</b></span>';}else{example.innerHTML='<span>Example: 0.2 + 0.5</span><span>2 tenths + 5 tenths = 7 tenths.</span><span><b>The example answer is 0.7.</b></span>';}});demoVideoObserver.observe(content,{childList:true,subtree:true});
const activeLessonObserver=new MutationObserver(()=>{const title=document.querySelector('.lesson-video .video-copy strong');const meta=document.querySelector('.practice-meta b');if(activeLesson&&title&&title.dataset.lesson!==activeLesson){title.dataset.lesson=activeLesson;title.textContent='Watch: '+selectedGrade+' Math · '+activeLesson;}if(activeLesson&&meta&&meta.dataset.lesson!==activeLesson){meta.dataset.lesson=activeLesson;meta.textContent=activeLesson.toUpperCase();}});activeLessonObserver.observe(content,{childList:true,subtree:true});
const lessonProgressObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;lessonQuestionCount=Math.min(lessonQuestionLimit,Math.max(0,lessonQuestionCount));const counter=document.querySelector('.practice-meta span:last-child');const bar=document.querySelector('.practice-shell .progress-line span');const desired='Question '+Math.min(lessonQuestionCount+1,lessonQuestionLimit)+' of '+lessonQuestionLimit;const width=Math.min(100,lessonQuestionCount/lessonQuestionLimit*100)+'%';if(counter&&counter.textContent!==desired&&counter.textContent.startsWith('Question'))counter.textContent=desired;if(bar&&bar.style.width!==width)bar.style.width=width;});lessonProgressObserver.observe(content,{childList:true,subtree:true});
const lessonExampleObserver=new MutationObserver(()=>{const example=document.querySelector('.lesson-video .video-example');if(!example||!activeLesson||example.dataset.lessonDemo===activeLesson)return;example.dataset.lessonDemo=activeLesson;const lesson=activeLesson.toLowerCase();if(lesson.includes('count'))example.innerHTML='<span>Example: What comes after 8?</span><span>Count one more: 9.</span><span><b>8 comes before 9.</b></span>';else if(lesson.includes('addition')||lesson.includes('add within'))example.innerHTML='<span>Example: 3 + 4</span><span>Start at 3 and count 4 more.</span><span><b>3 + 4 = 7</b></span>';else if(lesson.includes('multiplication'))example.innerHTML='<span>Example: 3 × 4</span><span>Three groups of four: 4 + 4 + 4.</span><span><b>3 × 4 = 12</b></span>';else if(lesson.includes('fraction'))example.innerHTML='<span>Example: 1/4 + 1/4</span><span>One fourth plus one fourth makes two fourths.</span><span><b>2/4 = 1/2</b></span>';else if(lesson.includes('equation'))example.innerHTML='<span>Example: x + 3 = 8</span><span>Subtract 3 from both sides.</span><span><b>x = 5</b></span>';else if(lesson.includes('quadratic'))example.innerHTML='<span>Example: x² = 25</span><span>5 × 5 = 25.</span><span><b>x = 5</b></span>';else if(lesson.includes('logarithm'))example.innerHTML='<span>Example: log₁₀(1000)</span><span>10³ = 1000.</span><span><b>The answer is 3</b></span>';else if(lesson.includes('derivative')||lesson.includes('calculus'))example.innerHTML='<span>Example: f(x) = x²</span><span>Its derivative is 2x.</span><span><b>At x = 3, f′(3) = 6</b></span>';else example.innerHTML='<span>Example: 0.2 + 0.5</span><span>2 tenths + 5 tenths = 7 tenths.</span><span><b>0.2 + 0.5 = 0.7</b></span>';});lessonExampleObserver.observe(content,{childList:true,subtree:true});
document.addEventListener('click',e=>{if(e.target.closest('.next-lesson-btn')){e.preventDefault();goToNextLesson();}});
document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-replay-lesson]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();const lesson=button.dataset.replayLesson;const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const lessonIndex=names.indexOf(lesson);if(lessonIndex<0)return;activeLessonIndex=lessonIndex;activeLesson=lesson;lessonQuestionCount=0;window.currentActiveLesson=lesson;window.currentLessonQuestionCount=0;localStorage.setItem(lessonIndexKey(),String(lessonIndex));clearPausedLesson();practiceView(lesson);},true);
function syncDailySummary(){if(localStorage.getItem('numoraTodayDate')===todayKey)todayCompleted=Number(localStorage.getItem('numoraTodayCompleted')||0);const stats=document.querySelectorAll('.stats-card .stat');if(stats[0]){const value=stats[0].querySelector('strong');const label=stats[0].querySelector('small');if(value)value.textContent=accuracyAttempts?Math.round(accuracyCorrect/accuracyAttempts*100)+'%':'—';if(label)label.textContent='Answer accuracy';}if(stats[1]){const value=stats[1].querySelector('strong');if(value)value.textContent=streak+' days';}if(stats[2]){const value=stats[2].querySelector('strong');const label=stats[2].querySelector('small');if(value)value.textContent=String(todayCompleted);if(label)label.textContent='Questions today';}const badgeCount=document.querySelector('.badge-count');if(badgeCount)badgeCount.textContent=String(badgeProgress.earned.length);const dueNav=document.querySelector('.flashcard-due-count');if(dueNav){const dueCount=readMistakeNotebook().filter(item=>!Number(item.reviewDueAt)||Number(item.reviewDueAt)<=Date.now()).length;dueNav.textContent=String(dueCount);dueNav.classList.toggle('hidden',dueCount===0);}}
const dailySaveObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;const feedback=document.querySelector('.feedback.success');if(feedback&&!feedback.dataset.saved){feedback.dataset.saved='true';todayCompleted++;monthCompleted++;lessonQuestionCount++;window.currentLessonQuestionCount=lessonQuestionCount;updateBadgeProgress(activeLesson);badgeProgress.lessonProgress=badgeProgress.lessonProgress||{};badgeProgress.lessonProgress[lessonKey(selectedGrade,activeLesson)]=Math.min(10,lessonQuestionCount);saveBadgeProgress();savePausedLesson();saveCurrentAccountProgress();localStorage.setItem('numoraTodayDate',todayKey);localStorage.setItem('numoraTodayCompleted',String(todayCompleted));localStorage.setItem('numoraMonthKey',monthKey);localStorage.setItem('numoraMonthCompleted',String(monthCompleted));const nextButton=document.querySelector('.check-btn');if(nextButton&&lessonQuestionCount>=lessonQuestionLimit){nextButton.textContent='Finish lesson ✓';nextButton.onclick=showLessonComplete;}else if(nextButton){nextButton.textContent='Next question →';nextButton.onclick=renderLessonQuestion;}}});dailySaveObserver.observe(content,{attributes:true,subtree:true,attributeFilter:['class']});
const homeLessonObserver=new MutationObserver(()=>{const card=document.querySelector('.continue-card');const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const lesson=names[savedLessonIndex()];const title=card?.querySelector('h2');if(title&&lesson&&title.dataset.homeLessonName!==lesson){title.dataset.homeLessonName=lesson;if(title.textContent!==lesson)title.textContent=lesson;}});homeLessonObserver.observe(content,{childList:true,subtree:true});
let toastDismissTimer=0;
function playCorrectAnswerSound(){const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;try{const context=new AudioContextClass(),oscillator=context.createOscillator(),gain=context.createGain();oscillator.type='sine';oscillator.frequency.value=660;gain.gain.setValueAtTime(0.0001,context.currentTime);gain.gain.exponentialRampToValueAtTime(0.06,context.currentTime+0.02);gain.gain.exponentialRampToValueAtTime(0.0001,context.currentTime+0.18);oscillator.connect(gain);gain.connect(context.destination);oscillator.start();oscillator.stop(context.currentTime+0.2);oscillator.onended=()=>context.close();}catch{}}
function showToast(message){if(message==='Question complete · +10 XP'){const boosts=Number(localStorage.getItem('numoraDoubleXpAnswers')||0);const award=boosts>0?20:10;if(boosts>0)localStorage.setItem('numoraDoubleXpAnswers',String(boosts-1));setXpBalance(getXpBalance()+award,boosts>0?'Correct answer · XP boost':'Correct answer');if(boosts>0)saveCurrentAccountProgress();message=`Question complete · +${award} XP`;if(localStorage.getItem('numoraSoundEffects')==='true')playCorrectAnswerSound();}toast.textContent=message;toast.classList.add('show');clearTimeout(toastDismissTimer);toastDismissTimer=setTimeout(()=>toast.classList.remove('show'),3000)}
function readHintPackInventory(){try{const saved=JSON.parse(localStorage.getItem('numoraHintPacks')||'{}');return saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{};}catch{return{};}}
function currentHintTopic(){const prompt=String(currentQuestion?.prompt||'').toLowerCase();const lesson=String(activeLesson||window.currentActiveLesson||'').toLowerCase();const text=prompt+' '+lesson;const tests=[['fractions',/fraction|numerator|denominator|mixed number/],['equations',/equation|solve for|\bx\s*[=+\-]|\bunknown\b/],['place-value',/place value|number comes after|number comes before|count forward|count backward/],['decimals',/decimal|tenths|hundredths/],['multiplication',/multipli|times|groups of|\b×\b|\*/],['division',/divid|quotient|shared equally|\b÷\b|remainder/],['geometry',/geometry|area|perimeter|angle|shape|triangle|rectangle|circle/],['time',/clock|time|minute|hour|calendar/],['measurement',/measure|length|width|height|weight|mass|volume|unit|centimeter|meter|inch|foot/],['patterns',/pattern|sequence|next in the series|rule/],['graphs',/graph|chart|plot|coordinate|data|table/],['word-problems',/word problem|how many are left|altogether|in all|each has|story problem/],['subtraction',/subtract|minus|take away|difference|\s-\s/],['addition',/add|addition|plus|sum|\s\+\s/]];return tests.find(([,pattern])=>pattern.test(text))?.[0]||'mixed-math';}
function hintCount(value){const count=Number(value);return Number.isFinite(count)?Math.max(0,Math.floor(count)):0;}
function availableHintTokens(topic=currentHintTopic()){const total=hintCount(localStorage.getItem('numoraHintTokens'));const packs=readHintPackInventory();const packed=Object.values(packs).reduce((sum,count)=>sum+hintCount(count),0);const generic=Math.max(0,total-packed);return Math.min(total,hintCount(packs[topic])+hintCount(packs['mixed-math'])+generic);}
function questionHint(topic=currentHintTopic()){const prompt=String(currentQuestion?.prompt||'').toLowerCase();const early=/^(pre-k|kindergarten|grade 1|grade 2)$/i.test(selectedGrade);const hints={addition:early?['Start with the first number and count on by the second.','Use your fingers or small groups to count everything.','Try counting forward one number at a time.']:['Break one addend into tens and ones, then add in parts.','Try making a friendly ten first, then add what remains.','Check whether switching the addends makes the calculation easier.'],subtraction:early?['Start with the bigger number and count backward.','Show the first amount, then take away the smaller group.','Count how many steps it takes to get from the smaller number to the bigger one.']:['Think of subtraction as finding the missing addend.','Break the amount being subtracted into tens and ones.','Estimate first, then check that the answer is smaller than the starting number.'],fractions:['Look at the denominators first; matching denominators let you work with the numerators.','If the denominators differ, rewrite the fractions with a common denominator.','For multiplication, multiply across; for division, multiply by the reciprocal.'],multiplication:['Think of the factors as equal-sized groups.','Use a known fact, then adjust it (for example, ×5 or ×10).','For larger numbers, split one factor into tens and ones and multiply in parts.'],division:['Ask how many equal groups fit into the total.','Use the related multiplication fact to find the quotient.','Estimate the quotient first and check by multiplying it back.'],equations:['Keep both sides balanced: whatever you do to one side, do to the other.','Undo addition or subtraction before undoing multiplication or division.','Substitute your value back into the original equation to check it.'],decimals:['Line up the decimal points before adding or subtracting.','Think of the digits as tenths, hundredths, or other place values.','Estimate the size of the answer, then check the decimal placement.'],geometry:['Identify the shape and what the question asks you to find.','Choose the matching rule or formula before using the measurements.','Check the units: area uses square units; perimeter uses regular units.'],measurement:['Check which units are given and which unit the answer needs.','Use a conversion fact or a ruler/scale model to compare the units.','Estimate whether the converted measurement should be larger or smaller.'],patterns:['Compare neighboring terms and look for a repeating change.','Check whether the pattern adds, subtracts, multiplies, or alternates.','Apply the same rule once more and verify it against earlier terms.'],'word-problems':['Underline what the question asks you to find.','Choose an operation using what is happening in the story.','Write a number sentence, solve it, and include the correct unit.'],'place-value':['Look at the digit’s position to tell its value.','Compare digits from left to right, starting with the greatest place.','Use a number line to check which number comes next or comes before.'],time:['Identify the starting time and the amount of time that passes.','Count by the right interval—minutes, hours, or days.','Check whether the time crosses an hour, noon, or midnight.'],graphs:['Read the title and labels before looking at the plotted values.','Find the correct row, bar, or coordinate for the question.','Compare the values and include the graph’s units in your answer.'],'mixed-math':['Write down what is known and what the question asks.','Choose one operation or rule that connects the known values.','Estimate the result and check whether it makes sense.']};let options=hints[topic]||hints['mixed-math'];if(prompt.includes('number comes after'))options=['Start at the number in the question and count forward one.','Say the counting numbers aloud and find the next one.','Use a number line and move one space to the right.'];const key='numoraHintCycle:'+selectedGrade+':'+String(activeLesson||'')+':'+prompt;const cycle=Math.max(0,Number(localStorage.getItem(key)||0));localStorage.setItem(key,String(cycle+1));let hint=options[cycle%options.length];if(selectedGrade&&selectedGrade!=='Pre-K'&&!early&&topic!=='place-value'&&topic!=='time'&&topic!=='graphs')hint=`${selectedGrade} hint: ${hint}`;return hint;}
function updateHintButton(button){const topic=currentHintTopic();const available=availableHintTokens(topic);const label=`Use ${topic==='mixed-math'?'math':topic.replace('-',' ')} hint · ${available}`;const title=available?'Uses a hint matched to this question and level.':`No ${topic.replace('-',' ')} hints available. Buy a matching hint pack or a Mixed Math pack.`;if(button.textContent!==label)button.textContent=label;if(button.disabled!==(available<1))button.disabled=available<1;if(button.title!==title)button.title=title;}
const xpHintObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;const controls=content.querySelector('.practice-controls');if(!controls)return;let hintButton=controls.querySelector('[data-use-hint]');if(!hintButton){hintButton=document.createElement('button');hintButton.type='button';hintButton.className='secondary-btn xp-hint-button';hintButton.dataset.useHint='';controls.appendChild(hintButton);}updateHintButton(hintButton);});
