let spokenQuestionText='';
const readQuestionObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;
  const question=content.querySelector('.practice-shell .question-card h1');
  const controls=content.querySelector('.practice-shell .question-card .practice-controls');
  const speech=window.speechSynthesis;
  if(!question||!controls){if(spokenQuestionText&&speech)speech.cancel();spokenQuestionText='';return;}
  const text=question.textContent.trim();
  if(spokenQuestionText&&spokenQuestionText!==text){speech?.cancel();spokenQuestionText='';}
  let button=controls.querySelector('[data-read-question]');
  if(!button){button=document.createElement('button');button.type='button';button.className='secondary-btn read-question-btn';button.dataset.readQuestion='';button.textContent='🔊 Read question';button.setAttribute('aria-label','Read question aloud');controls.insertBefore(button,controls.firstChild);}
  if(localStorage.getItem('numoraAutoRead')==='true'&&button.dataset.autoReadText!==text){button.dataset.autoReadText=text;setTimeout(()=>{if(button.isConnected)button.click();},0);}
  if(button.dataset.bound==='true')return;
  button.dataset.bound='true';
  button.addEventListener('click',()=>{
    if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined'){showToast('Read aloud is not available in this browser.');return;}
    if(window.speechSynthesis.speaking&&spokenQuestionText===text){window.speechSynthesis.cancel();spokenQuestionText='';button.textContent='🔊 Read question';button.setAttribute('aria-label','Read question aloud');return;}
    window.speechSynthesis.cancel();
    const utterance=new SpeechSynthesisUtterance(text);utterance.rate=0.9;spokenQuestionText=text;button.textContent='■ Stop reading';button.setAttribute('aria-label','Stop reading question');
    const reset=()=>{if(spokenQuestionText===text){spokenQuestionText='';button.textContent='🔊 Read question';button.setAttribute('aria-label','Read question aloud');}};
    utterance.onend=reset;utterance.onerror=reset;window.speechSynthesis.speak(utterance);
  });
});
readQuestionObserver.observe(content,{childList:true,subtree:true,characterData:true});
document.addEventListener('click',e=>{const actionButton=e.target.closest('[data-action="review-mistake"],[data-action="clear-mistake"]');if(actionButton){e.preventDefault();e.stopImmediatePropagation();if(actionButton.dataset.action==='review-mistake'){selectedGrade=actionButton.dataset.grade;localStorage.setItem('numoraGrade',selectedGrade);syncProfile();practiceView(actionButton.dataset.lesson);}else{const id=decodeURIComponent(actionButton.dataset.mistakeId||'');saveMistakeNotebook(readMistakeNotebook().filter(item=>item.id!==id));mistakesView();showToast('Removed from your notebook');}return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='start-challenge'){e.preventDefault();startChallenge();return;}if(action==='toggle-challenge-pause'){e.preventDefault();challengePaused=!challengePaused;const pauseButton=e.target.closest('[data-action=toggle-challenge-pause]');if(pauseButton){pauseButton.textContent=challengePaused?'Resume timer':'Pause timer';pauseButton.setAttribute('aria-pressed',String(challengePaused));}document.querySelector('.answer-input').disabled=challengePaused;document.querySelector('[data-action=submit-challenge]').disabled=challengePaused;document.querySelector('[data-action=skip-challenge]').disabled=challengePaused;return;}if(action==='retry-challenge'){e.preventDefault();startChallenge({duration:challengeDuration,mode:challengeMode,difficulty:challengeDifficulty});return;}if(action==='practice-random-saved'){e.preventDefault();const cards=[...content.querySelectorAll('.saved-skill-card')];if(cards.length){const card=cards[Math.floor(Math.random()*cards.length)];selectedGrade=card.dataset.grade;localStorage.setItem('numoraGrade',selectedGrade);syncProfile();practiceView(card.dataset.lesson);}return;}if(action==='replay-challenge'){e.preventDefault();const replay=e.target.closest('[data-action=replay-challenge]');const duration=document.querySelector('#challenge-duration'),mode=document.querySelector('#challenge-mode'),difficulty=document.querySelector('#challenge-difficulty');if(duration&&mode&&difficulty&&replay){duration.value=['30','60','90','120','180'].includes(replay.dataset.duration)?replay.dataset.duration:'60';mode.value=['mixed','addition','subtraction','multiplication','division'].includes(replay.dataset.mode)?replay.dataset.mode:'mixed';difficulty.value=['warmup','standard','stretch'].includes(replay.dataset.difficulty)?replay.dataset.difficulty:'standard';startChallenge();}return;}if(action==='skip-challenge'){e.preventDefault();challengeSkipped++;challengeStreak=0;challengeQuestion++;renderChallengeQuestion();return;}if(action==='submit-challenge'){e.preventDefault();const input=document.querySelector('.answer-input');if(!input||input.value.trim()==='')return;challengeAnswered++;if(Number(input.value)===challengeAnswer){challengeScore++;challengeStreak++;challengeBestStreak=Math.max(challengeBestStreak,challengeStreak);showToast('Correct! +10 XP');setXpBalance(getXpBalance()+10);if(challengeStreak%5===0){setXpBalance(getXpBalance()+25);const spanish=localStorage.getItem('numoraLanguage')==='es';showToast(spanish?'¡Racha de 5! +25 XP extra':'5-answer streak! +25 bonus XP');}}else{const spanish=localStorage.getItem('numoraLanguage')==='es';showToast(spanish?`¡No exactamente! La respuesta era ${challengeAnswer}.`:`Not quite! The answer was ${challengeAnswer}.`);}challengeQuestion++;renderChallengeQuestion();return;}if(action==='custom-random-lesson'||action==='custom-next-lesson'){e.preventDefault();const select=document.querySelector('#custom-lesson');if(select){const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];const lesson=action==='custom-next-lesson'?resumeLessonName():names[Math.floor(Math.random()*names.length)];if(names.includes(lesson)){select.value=lesson;select.dispatchEvent(new Event('change',{bubbles:true}));showToast(action==='custom-next-lesson'?'Your next lesson is ready.':'Random lesson picked!');}}return;}if(action==='start-custom-quiz'){e.preventDefault();startCustomQuiz();return;}const view=e.target.closest('[data-view]')?.dataset.view;if(view){const views={home:homeView,skills:skillsView,saved:savedSkillsView,reports:reportsView,mistakes:mistakesView,flashcards:flashcardsView,goals:goalsView,badges:badgesView,challenge:challengeView,review:reviewView,parent:parentView,leaderboard:leaderboardView,custom:customQuizView};views[view]?.();document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));}if(e.target.closest('[data-practice]')){practiceView(e.target.closest('[data-practice]').dataset.lesson);}});

const mistakeObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;const feedback=document.querySelector('.practice-shell .feedback.error');if(!feedback)return;const input=document.querySelector('.practice-shell .answer-input');if(!input||!input.value.trim())return;const stamp=`${currentQuestion?.prompt||''}|${input.value.trim()}`;if(feedback.dataset.savedMistake===stamp)return;feedback.dataset.savedMistake=stamp;recordPracticeMistake(input.value.trim());});
