let studyClockSeconds=0,studyClockStartedAt=0,studyClockInterval=null;
function renderStudyClock(){const label=content.querySelector('[data-study-clock]');if(!label)return;const total=studyClockSeconds+(studyClockStartedAt?Math.floor((Date.now()-studyClockStartedAt)/1000):0);label.textContent=`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function toggleStudyClock(button){if(studyClockStartedAt){studyClockSeconds+=Math.floor((Date.now()-studyClockStartedAt)/1000);studyClockStartedAt=0;clearInterval(studyClockInterval);studyClockInterval=null;button.textContent='Resume focus timer';}else{studyClockStartedAt=Date.now();button.textContent='Pause focus timer';studyClockInterval=setInterval(renderStudyClock,1000);}renderStudyClock();}
const lessonToolsObserver=new MutationObserver(()=>{if(content.querySelector('[data-challenge-time]'))return;const controls=content.querySelector('.practice-shell .practice-controls');if(!controls){if(studyClockStartedAt){studyClockSeconds+=Math.floor((Date.now()-studyClockStartedAt)/1000);studyClockStartedAt=0;clearInterval(studyClockInterval);studyClockInterval=null;}return;}if(!controls.querySelector('[data-action="skip-question"]')){const skip=document.createElement('button');skip.type='button';skip.className='secondary-btn';skip.dataset.action='skip-question';skip.textContent='Try another question';controls.appendChild(skip);}if(!content.querySelector('.focus-clock')){const clock=document.createElement('div');clock.className='focus-clock';clock.innerHTML='<span>⏳ Focus time <strong data-study-clock>00:00</strong></span><button type="button" class="secondary-btn" data-action="toggle-focus-clock"></button>';controls.before(clock);const timerButton=clock.querySelector('[data-action="toggle-focus-clock"]');timerButton.textContent=studyClockStartedAt?'Pause focus timer':'Start timer';renderStudyClock();}});
lessonToolsObserver.observe(content,{subtree:true,childList:true});
