document.addEventListener('click',event=>{const button=event.target instanceof Element?event.target.closest('[data-action="start-daily-warmup"]'):null;if(!button)return;event.preventDefault();event.stopImmediatePropagation();challengeView();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.view==='challenge'));startChallenge({duration:60,mode:'mixed',difficulty:'warmup'});},true);

function mathReferenceItems(grade=selectedGrade){const spanish=localStorage.getItem('numoraLanguage')==='es';const rank=/^Grade (\d+)$/.exec(grade),n=rank?Number(rank[1]):grade==='College'?13:grade==='Kindergarten'?0:0;const early=n<=2;const elementary=n>=3&&n<=5;const middle=n>=6&&n<=8;const college=n>=13;const enEarly=[['Counting on','Start at the larger number and count forward by the smaller amount.','8 + 3 → 9, 10, 11, so the total is 11.'],['Place value','A digit’s place tells how much it is worth: ones, tens, hundreds.','In 352, the 5 means 5 tens, or 50.'],['Compare numbers','Compare digits from left to right, starting with the greatest place.','47 is greater than 39 because 4 tens is more than 3 tens.'],['Shapes','Count sides and corners to help name a flat shape.','A triangle has 3 sides and 3 corners.'],['Even and odd','Even numbers split into pairs with none left over.','12 is even; 13 leaves one unpaired.']];const esEarly=[['Contar hacia adelante','Empieza con el número mayor y cuenta hacia adelante la cantidad menor.','8 + 3 → 9, 10, 11; el total es 11.'],['Valor posicional','La posición de un dígito indica su valor: unidades, decenas, centenas.','En 352, el 5 vale 5 decenas, o 50.'],['Comparar números','Compara los dígitos de izquierda a derecha, empezando por la posición mayor.','47 es mayor que 39 porque 4 decenas superan 3.'],['Figuras','Cuenta los lados y las esquinas para nombrar una figura plana.','Un triángulo tiene 3 lados y 3 esquinas.'],['Pares e impares','Los números pares se pueden dividir en parejas sin que sobre ninguno.','12 es par; de 13 sobra uno.']];const enElementary=[['Multiplication','Multiplication counts equal groups: groups × items in each group.','4 × 6 means 4 groups of 6, which is 24.'],['Long division','Divide, multiply, subtract, bring down, then repeat. Check with divisor × quotient + remainder.','156 ÷ 12 = 13 because 12 × 13 = 156.'],['Fractions','For equal denominators, add or subtract the numerators and keep the denominator.','2/8 + 3/8 = 5/8.'],['Equivalent fractions','Multiply or divide the numerator and denominator by the same nonzero number.','3/4 = 6/8 because both parts were multiplied by 2.'],['Decimals','Line up decimal points when adding or subtracting.','1.25 + 0.60 = 1.85.'],['Area and perimeter','Rectangle area = length × width. Perimeter = 2 × (length + width).','For 5 by 3: area = 15 square units; perimeter = 16 units.']];const esElementary=[['Multiplicación','La multiplicación cuenta grupos iguales: grupos × elementos en cada grupo.','4 × 6 significa 4 grupos de 6, que son 24.'],['División larga','Divide, multiplica, resta, baja el siguiente dígito y repite. Comprueba: divisor × cociente + residuo.','156 ÷ 12 = 13 porque 12 × 13 = 156.'],['Fracciones','Con denominadores iguales, suma o resta los numeradores y conserva el denominador.','2/8 + 3/8 = 5/8.'],['Fracciones equivalentes','Multiplica o divide el numerador y el denominador por el mismo número distinto de cero.','3/4 = 6/8 porque multiplicamos ambas partes por 2.'],['Decimales','Alinea los puntos decimales al sumar o restar.','1.25 + 0.60 = 1.85.'],['Área y perímetro','Área del rectángulo = largo × ancho. Perímetro = 2 × (largo + ancho).','Para 5 por 3: área = 15 unidades cuadradas; perímetro = 16 unidades.']];const enMiddle=[['Integers','Subtracting a number is adding its opposite.','7 − (−3) = 7 + 3 = 10.'],['Order of operations','Use parentheses, exponents, multiplication/division left to right, then addition/subtraction left to right.','3 + 2 × 5 = 3 + 10 = 13.'],['Ratios','A ratio compares quantities. Keep the order and units clear.','2 red for every 3 blue → ratio 2:3.'],['Percent','Percent means “out of 100.” Convert percent to a decimal by dividing by 100.','25% = 0.25 = 1/4.'],['Solve equations','Undo operations in reverse order and do the same thing to both sides.','3x + 4 = 19 → 3x = 15 → x = 5.'],['Triangle angles','The interior angles of a triangle add to 180°.','If two angles are 65° and 45°, the third is 70°.']];const esMiddle=[['Enteros','Restar un número equivale a sumar su opuesto.','7 − (−3) = 7 + 3 = 10.'],['Orden de operaciones','Usa paréntesis, exponentes, multiplicación/división de izquierda a derecha y luego suma/resta.','3 + 2 × 5 = 3 + 10 = 13.'],['Razones','Una razón compara cantidades. Mantén claro el orden y las unidades.','2 rojas por cada 3 azules → razón 2:3.'],['Porcentaje','Porcentaje significa “de cada 100”. Divide entre 100 para convertirlo a decimal.','25% = 0.25 = 1/4.'],['Resolver ecuaciones','Deshaz las operaciones en orden inverso y haz lo mismo en ambos lados.','3x + 4 = 19 → 3x = 15 → x = 5.'],['Ángulos de triángulos','Los ángulos interiores de un triángulo suman 180°.','Si dos ángulos son 65° y 45°, el tercero es 70°.']];const enHigh=[['Linear equations','Isolate the variable by applying inverse operations to both sides.','2x − 7 = 9 → 2x = 16 → x = 8.'],['Slope','Slope = change in y ÷ change in x = (y₂ − y₁)/(x₂ − x₁).','From (1, 2) to (4, 8), slope = 6/3 = 2.'],['Quadratic formula','For ax² + bx + c = 0, x = (−b ± √(b² − 4ac))/(2a).','For x² − 5x + 6 = 0, roots are 2 and 3.'],['Exponent rules','When multiplying same bases, add exponents; when dividing, subtract them.','x³ × x² = x⁵; x⁶ ÷ x² = x⁴.'],['Right triangles','Pythagorean theorem: a² + b² = c², where c is the hypotenuse.','Legs 6 and 8 give c = √(36 + 64) = 10.'],['Mean','Mean = sum of values ÷ number of values.','For 4, 6, 8: mean = 18 ÷ 3 = 6.']];const esHigh=[['Ecuaciones lineales','Aísla la variable aplicando operaciones inversas en ambos lados.','2x − 7 = 9 → 2x = 16 → x = 8.'],['Pendiente','Pendiente = cambio en y ÷ cambio en x = (y₂ − y₁)/(x₂ − x₁).','De (1, 2) a (4, 8), la pendiente = 6/3 = 2.'],['Fórmula cuadrática','Para ax² + bx + c = 0, x = (−b ± √(b² − 4ac))/(2a).','Para x² − 5x + 6 = 0, las raíces son 2 y 3.'],['Reglas de exponentes','Al multiplicar bases iguales, suma exponentes; al dividir, réstalos.','x³ × x² = x⁵; x⁶ ÷ x² = x⁴.'],['Triángulos rectángulos','Teorema de Pitágoras: a² + b² = c², donde c es la hipotenusa.','Catetos 6 y 8 dan c = √(36 + 64) = 10.'],['Media','Media = suma de los valores ÷ cantidad de valores.','Para 4, 6, 8: media = 18 ÷ 3 = 6.']];const es=spanish;let list=early?(es?esEarly:enEarly):elementary?(es?esElementary:enElementary):middle?(es?esMiddle:enMiddle):(es?esHigh:enHigh);if(college){list=list.concat(es?[['Derivada','La derivada representa la tasa de cambio instantánea.','Si f(x) = x², entonces f′(x) = 2x.'],['Regla de potencia','La derivada de xⁿ es n·xⁿ⁻¹.','d/dx(x⁴) = 4x³.']]:[['Derivative','A derivative represents instantaneous rate of change.','If f(x) = x², then f′(x) = 2x.'],['Power rule','The derivative of xⁿ is n·xⁿ⁻¹.','d/dx(x⁴) = 4x³.']]);}return list;}
function mathReferenceView(){const es=localStorage.getItem('numoraLanguage')==='es',items=mathReferenceItems();pageTitle.textContent=es?'Referencia de matemáticas':'Math reference';content.innerHTML=`<div class="page-wrap math-reference-page"><div class="hero-row"><div><span class="eyebrow">${es?'CONSULTA RÁPIDA':'STUDY TOOL'}</span><h1>${es?'Referencia de matemáticas':'Math reference'}</h1><p>${es?`Reglas y ejemplos breves para ${escapeHtmlText(selectedGrade)}.`:`Quick rules and worked examples for ${escapeHtmlText(selectedGrade)}.`}</p></div><button type="button" class="secondary-btn" data-reference-print>${es?'Imprimir':'Print'}</button></div><label class="notes-search-label" for="reference-search">${es?'Buscar en las reglas':'Search the reference'}</label><input class="notes-search" id="reference-search" type="search" placeholder="${es?'Prueba fracciones, área, ecuaciones…':'Try fractions, area, equations…'}" autocomplete="off"><div class="math-reference-grid">${items.map(([title,rule,example])=>`<article class="card math-reference-card" data-reference-card><span class="skill-tag">${escapeHtmlText(selectedGrade)}</span><h2>${escapeHtmlText(title)}</h2><p>${escapeHtmlText(rule)}</p><div class="reference-example"><strong>${es?'Ejemplo':'Example'}</strong><p>${escapeHtmlText(example)}</p></div></article>`).join('')}</div><p class="notes-empty hidden" data-reference-empty role="status">${es?'No hay reglas que coincidan.':'No matching reference cards.'}</p></div>`;}
document.addEventListener('click',event=>{const nav=event.target instanceof Element?event.target.closest('[data-view="reference"]'):null;const print=event.target instanceof Element?event.target.closest('[data-reference-print]'):null;if(nav){event.preventDefault();event.stopImmediatePropagation();mathReferenceView();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));return;}if(print){event.preventDefault();window.print();}},true);
document.addEventListener('input',event=>{if(!(event.target instanceof Element)||event.target.id!=='reference-search')return;const query=event.target.value.trim().toLocaleLowerCase();let visible=0;content.querySelectorAll('[data-reference-card]').forEach(card=>{const matches=card.textContent.toLocaleLowerCase().includes(query);card.classList.toggle('hidden',!matches);if(matches)visible++;});content.querySelector('[data-reference-empty]')?.classList.toggle('hidden',visible>0);});

function vocabularyItems(){const spanish=localStorage.getItem('numoraLanguage')==='es';const grade=/^Grade (\d+)$/.exec(selectedGrade);const level=selectedGrade==='College'?'college':grade&&Number(grade[1])>=9?'high':grade&&Number(grade[1])>=6?'middle':grade&&Number(grade[1])>=3?'elementary':'early';const terms={early:[['Number','A number tells how many or which position.','There are 5 blocks.','Número','Un número indica cuántos hay o qué posición ocupa.','Hay 5 bloques.'],['Add','To add is to put groups together and find the total.','2 + 3 = 5','Sumar','Sumar es juntar grupos para encontrar el total.','2 + 3 = 5'],['Subtract','To subtract is to take away or find the difference.','7 − 2 = 5','Restar','Restar es quitar o encontrar la diferencia.','7 − 2 = 5'],['Equal','Equal means two amounts have the same value.','4 + 1 = 5','Igual','Igual significa que dos cantidades tienen el mismo valor.','4 + 1 = 5'],['Pattern','A pattern repeats or changes by a rule.','2, 4, 6, 8 adds 2 each time.','Patrón','Un patrón se repite o cambia siguiendo una regla.','2, 4, 6, 8 aumenta de 2 en 2.']],elementary:[['Factor','A factor is a number multiplied by another number.','3 and 4 are factors of 12.','Factor','Un factor es un número que se multiplica por otro.','3 y 4 son factores de 12.'],['Product','A product is the answer to a multiplication problem.','6 × 4 = 24; 24 is the product.','Producto','El producto es la respuesta de una multiplicación.','6 × 4 = 24; 24 es el producto.'],['Quotient','A quotient is the answer to a division problem.','20 ÷ 5 = 4; 4 is the quotient.','Cociente','El cociente es la respuesta de una división.','20 ÷ 5 = 4; 4 es el cociente.'],['Numerator','The numerator is the top number in a fraction.','In 3/8, 3 is the numerator.','Numerador','El numerador es el número de arriba en una fracción.','En 3/8, 3 es el numerador.'],['Denominator','The denominator is the bottom number in a fraction.','In 3/8, 8 is the denominator.','Denominador','El denominador es el número de abajo en una fracción.','En 3/8, 8 es el denominador.'],['Perimeter','Perimeter is the distance around a shape.','A 4-by-3 rectangle has perimeter 14 units.','Perímetro','El perímetro es la distancia alrededor de una figura.','Un rectángulo de 4 por 3 tiene 14 unidades de perímetro.']],middle:[['Integer','An integer is a whole number, its opposite, or zero.','−3, 0, and 8 are integers.','Entero','Un entero es un número entero positivo, su opuesto o cero.','−3, 0 y 8 son enteros.'],['Ratio','A ratio compares two amounts.','2 cups to 3 cups is a 2:3 ratio.','Razón','Una razón compara dos cantidades.','2 tazas por 3 tazas es una razón de 2:3.'],['Variable','A variable is a letter that stands for an unknown or changing number.','In x + 4 = 9, x is the variable.','Variable','Una variable es una letra que representa un número desconocido o cambiante.','En x + 4 = 9, x es la variable.'],['Coefficient','A coefficient is the number multiplying a variable.','In 5y, the coefficient is 5.','Coeficiente','Un coeficiente es el número que multiplica una variable.','En 5y, el coeficiente es 5.'],['Percent','A percent is a number of parts out of 100.','25% means 25 out of 100.','Porcentaje','Un porcentaje indica cuántas partes hay de cada 100.','25% significa 25 de cada 100.'],['Mean','The mean is the total divided equally by the number of values.','Mean of 2, 4, and 6 is 12 ÷ 3 = 4.','Media','La media es el total dividido entre la cantidad de valores.','La media de 2, 4 y 6 es 12 ÷ 3 = 4.']],high:[['Exponent','An exponent tells how many times to use a base as a factor.','3⁴ = 3 × 3 × 3 × 3 = 81.','Exponente','Un exponente indica cuántas veces se usa la base como factor.','3⁴ = 3 × 3 × 3 × 3 = 81.'],['Slope','Slope measures vertical change divided by horizontal change.','From (1, 2) to (3, 8), slope = 6 ÷ 2 = 3.','Pendiente','La pendiente mide el cambio vertical dividido entre el horizontal.','De (1, 2) a (3, 8), la pendiente = 6 ÷ 2 = 3.'],['Function','A function gives exactly one output for each input.','If f(x) = 2x, then f(3) = 6.','Función','Una función asigna exactamente un resultado a cada entrada.','Si f(x) = 2x, entonces f(3) = 6.'],['Quadratic','A quadratic expression has a variable with highest exponent 2.','x² + 3x + 2 is quadratic.','Cuadrática','Una expresión cuadrática tiene una variable cuyo mayor exponente es 2.','x² + 3x + 2 es cuadrática.'],['Hypotenuse','The hypotenuse is the longest side, opposite the right angle.','A 3-4-5 right triangle has hypotenuse 5.','Hipotenusa','La hipotenusa es el lado más largo, opuesto al ángulo recto.','Un triángulo rectángulo 3-4-5 tiene hipotenusa 5.'],['Probability','Probability measures how likely an event is, from 0 to 1.','A fair coin has a 1/2 chance of heads.','Probabilidad','La probabilidad mide qué tan posible es un evento, de 0 a 1.','Una moneda justa tiene 1/2 de probabilidad de caer cara.']],college:[['Derivative','A derivative describes an instantaneous rate of change.','For f(x) = x², f′(x) = 2x.','Derivada','Una derivada describe una tasa de cambio instantánea.','Para f(x) = x², f′(x) = 2x.'],['Integral','An integral can represent accumulated change or signed area.','∫₀² x dx = 2.','Integral','Una integral puede representar el cambio acumulado o el área con signo.','∫₀² x dx = 2.'],['Limit','A limit describes the value a function approaches near an input.','As x approaches 2, x + 3 approaches 5.','Límite','Un límite describe el valor al que se acerca una función cerca de una entrada.','Cuando x se acerca a 2, x + 3 se acerca a 5.'],['Vector','A vector has both magnitude and direction.','(3, 4) has length 5.','Vector','Un vector tiene magnitud y dirección.','(3, 4) tiene longitud 5.'],['Matrix','A matrix is a rectangular arrangement of values.','[[1, 2], [3, 4]] is a 2-by-2 matrix.','Matriz','Una matriz es una disposición rectangular de valores.','[[1, 2], [3, 4]] es una matriz de 2 por 2.'],['Standard deviation','Standard deviation describes how spread out data values are.','A small standard deviation means values cluster near the mean.','Desviación estándar','La desviación estándar describe qué tan dispersos están los datos.','Una desviación pequeña indica que los valores están cerca de la media.']]};return (terms[level]||terms.early).map(([en,def,ex,es,defEs,exEs])=>[spanish?es:en,spanish?defEs:def,spanish?exEs:ex]);}
function mathVocabularyView(){const es=localStorage.getItem('numoraLanguage')==='es',items=vocabularyItems();pageTitle.textContent=es?'Vocabulario matemático':'Math vocabulary';content.innerHTML=`<div class="page-wrap math-vocabulary-page"><div class="hero-row"><div><span class="eyebrow">${es?'PALABRAS CLAVE':'LEARNING TOOL'}</span><h1>${es?'Vocabulario matemático':'Math vocabulary'}</h1><p>${es?`Términos matemáticos para ${escapeHtmlText(selectedGrade)}, con definiciones y ejemplos.`:`Key math terms for ${escapeHtmlText(selectedGrade)}, with clear definitions and examples.`}</p></div></div><label class="notes-search-label" for="vocabulary-search">${es?'Buscar palabras':'Search words'}</label><input class="notes-search" id="vocabulary-search" type="search" placeholder="${es?'Busca una palabra matemática…':'Search a math word…'}" autocomplete="off"><div class="math-reference-grid">${items.map(([term,definition,example])=>`<article class="card vocabulary-card" data-vocabulary-card><span class="skill-tag">${escapeHtmlText(selectedGrade)}</span><h2>${escapeHtmlText(term)}</h2><p>${escapeHtmlText(definition)}</p><div class="reference-example"><strong>${es?'Ejemplo':'Example'}</strong><p>${escapeHtmlText(example)}</p></div></article>`).join('')}</div><p class="notes-empty hidden" data-vocabulary-empty role="status">${es?'No hay palabras que coincidan.':'No matching words found.'}</p></div>`;}
document.addEventListener('click',event=>{const nav=event.target instanceof Element?event.target.closest('[data-view="vocabulary"]'):null;if(!nav)return;event.preventDefault();event.stopImmediatePropagation();mathVocabularyView();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));},true);
document.addEventListener('input',event=>{if(!(event.target instanceof Element)||event.target.id!=='vocabulary-search')return;const query=event.target.value.trim().toLocaleLowerCase();let visible=0;content.querySelectorAll('[data-vocabulary-card]').forEach(card=>{const matches=card.textContent.toLocaleLowerCase().includes(query);card.classList.toggle('hidden',!matches);if(matches)visible++;});content.querySelector('[data-vocabulary-empty]')?.classList.toggle('hidden',visible>0);});

let currentWordProblem=null,wordProblemHintIndex=0,wordProblemScore=0,wordProblemAttempts=0;
function makeWordProblem(promptEn,promptEs,answer,hintsEn,hintsEs,solutionEn,solutionEs){const es=localStorage.getItem('numoraLanguage')==='es';return{prompt:es?promptEs:promptEn,answer,hints:es?hintsEs:hintsEn,solution:es?solutionEs:solutionEn};}
function createWordProblem(){const grade=/^Grade (\d+)$/.exec(selectedGrade),n=grade?Number(grade[1]):selectedGrade==='College'?13:0,r=(min,max)=>Math.floor(Math.random()*(max-min+1))+min;
if(n<=2||selectedGrade==='Pre-K'||selectedGrade==='Kindergarten'){const add=Math.random()<.5,a=r(2,6),b=add?r(1,9-a):r(1,a);return add?makeWordProblem(`Mia has ${a} stickers and gets ${b} more. How many stickers does she have now?`,`Mia tiene ${a} pegatinas y recibe ${b} más. ¿Cuántas tiene ahora?`,a+b,[`Start with ${a} and count forward ${b} more.`,`Put the two groups together: ${a} + ${b}.`],[`Empieza en ${a} y cuenta ${b} más.`,`Junta los dos grupos: ${a} + ${b}.`],`${a} + ${b} = ${a+b} stickers.`,` ${a} + ${b} = ${a+b} pegatinas.`):makeWordProblem(`There are ${a} balloons. ${b} float away. How many are left?`,`Hay ${a} globos. ${b} se vuelan. ¿Cuántos quedan?`,a-b,[`Take away ${b} from ${a}.`,`Count back ${b} steps from ${a}.`],[`Quita ${b} de ${a}.`,`Cuenta hacia atrás ${b} desde ${a}.`],`${a} − ${b} = ${a-b} balloons.`,`${a} − ${b} = ${a-b} globos.`);}
if(n<=5){const kind=r(0,2);if(kind===0){const a=r(3,9),b=r(2,9);return makeWordProblem(`A garden has ${a} rows with ${b} plants in each row. How many plants are there?`,`Un jardín tiene ${a} filas con ${b} plantas en cada fila. ¿Cuántas plantas hay?`,a*b,[`There are ${a} equal groups of ${b}.`,`Multiply ${a} × ${b}.`],[`Hay ${a} grupos iguales de ${b}.`,`Multiplica ${a} × ${b}.`],`${a} × ${b} = ${a*b} plants.`,`${a} × ${b} = ${a*b} plantas.`);}if(kind===1){const length=r(3,12),width=r(2,9);return makeWordProblem(`A rectangular rug is ${length} feet long and ${width} feet wide. What is its area in square feet?`,`Una alfombra rectangular mide ${length} pies de largo y ${width} de ancho. ¿Cuál es su área en pies cuadrados?`,length*width,[`Area is length times width.`,`Multiply ${length} × ${width}.`],[`El área es largo por ancho.`,`Multiplica ${length} × ${width}.`],`${length} × ${width} = ${length*width} square feet.`,`${length} × ${width} = ${length*width} pies cuadrados.`);}const divisor=r(2,9),quotient=r(12,40),total=divisor*quotient;return makeWordProblem(`${total} cards are shared equally among ${divisor} students. How many cards does each student get?`,`Se reparten ${total} tarjetas en partes iguales entre ${divisor} estudiantes. ¿Cuántas recibe cada uno?`,quotient,[`Sharing equally means divide ${total} by ${divisor}.`,`Find ${total} ÷ ${divisor}.`],[`Repartir por igual significa dividir ${total} entre ${divisor}.`,`Calcula ${total} ÷ ${divisor}.`],`${total} ÷ ${divisor} = ${quotient} cards each.`,`${total} ÷ ${divisor} = ${quotient} tarjetas para cada uno.`);}
if(n<=8){const kind=r(0,2);if(kind===0){const rate=[10,20,25,50][r(0,3)],whole=[40,60,80,100,120][r(0,4)],answer=rate*whole/100;return makeWordProblem(`A ${rate}% discount is taken off a $${whole} backpack. How many dollars are saved?`,`Se descuenta un ${rate}% de una mochila que cuesta $${whole}. ¿Cuántos dólares se ahorran?`,answer,[`${rate}% means ${rate} out of every 100.`,`Multiply ${whole} by ${rate}/100.`],[`${rate}% significa ${rate} de cada 100.`,`Multiplica ${whole} por ${rate}/100.`],`${whole} × ${rate}/100 = $${answer} saved.`,`${whole} × ${rate}/100 = $${answer} de ahorro.`);}if(kind===1){const x=r(3,12),b=r(2,15),total=x+b;return makeWordProblem(`A number plus ${b} equals ${total}. What is the number?`,`Un número más ${b} es igual a ${total}. ¿Cuál es el número?`,x,[`Undo adding ${b} by subtracting it from ${total}.`,`Solve ${total} − ${b}.`],[`Deshaz la suma de ${b} restándolo de ${total}.`,`Calcula ${total} − ${b}.`],`x + ${b} = ${total}, so x = ${total} − ${b} = ${x}.`,`x + ${b} = ${total}, entonces x = ${total} − ${b} = ${x}.`);}const per=r(3,8),groups=r(3,8),answer=per*groups;return makeWordProblem(`A recipe uses ${per} cups of flour for one batch. How many cups are needed for ${groups} batches?`,`Una receta usa ${per} tazas de harina por tanda. ¿Cuántas tazas se necesitan para ${groups} tandas?`,answer,[`The same amount is used for each batch.`,`Multiply ${per} × ${groups}.`],[`Se usa la misma cantidad en cada tanda.`,`Multiplica ${per} × ${groups}.`],`${per} × ${groups} = ${answer} cups.`,`${per} × ${groups} = ${answer} tazas.`);}
if(n<=12){const kind=r(0,2);if(kind===0){const a=r(2,9),x=r(4,15),b=r(1,12),c=a*x+b;return makeWordProblem(`A taxi charges $${b} plus $${a} per mile. The ride costs $${c}. How many miles was the ride?`,`Un taxi cobra $${b} más $${a} por milla. El viaje cuesta $${c}. ¿Cuántas millas duró?`,x,[`Subtract the starting fee $${b} from $${c}.`,`Divide the remaining cost by $${a} per mile.`],[`Resta la tarifa inicial de $${b} a los $${c}.`,`Divide el costo restante entre $${a} por milla.`],`${a}x + ${b} = ${c}; x = (${c} − ${b}) ÷ ${a} = ${x} miles.`,`${a}x + ${b} = ${c}; x = (${c} − ${b}) ÷ ${a} = ${x} millas.`);}if(kind===1){const x1=r(0,5),y1=r(1,12),dx=r(1,5),m=r(1,6),x2=x1+dx,y2=y1+m*dx;return makeWordProblem(`A line passes through (${x1}, ${y1}) and (${x2}, ${y2}). What is its slope?`,`Una recta pasa por (${x1}, ${y1}) y (${x2}, ${y2}). ¿Cuál es su pendiente?`,m,[`Slope is change in y divided by change in x.`,`Calculate (${y2} − ${y1}) ÷ (${x2} − ${x1}).`],[`La pendiente es el cambio en y dividido entre el cambio en x.`,`Calcula (${y2} − ${y1}) ÷ (${x2} − ${x1}).`],`(${y2} − ${y1}) ÷ (${x2} − ${x1}) = ${m}.`,`(${y2} − ${y1}) ÷ (${x2} − ${x1}) = ${m}.`);}const mean=r(6,12),a=mean-2,b=mean+1,c=mean+2,x=mean-1,total=4*mean;return makeWordProblem(`A data set has values ${a}, ${b}, ${c}, and one more value x. Its mean is ${mean}. What is x?`,`Un conjunto de datos tiene ${a}, ${b}, ${c} y otro valor x. Su media es ${mean}. ¿Cuánto vale x?`,x,[`The total of four values must be 4 × ${mean}.`,`Subtract ${a} + ${b} + ${c} from that total.`],[`El total de cuatro valores debe ser 4 × ${mean}.`,`Resta ${a} + ${b} + ${c} de ese total.`],`x = 4 × ${mean} − (${a} + ${b} + ${c}) = ${x}.`,`x = 4 × ${mean} − (${a} + ${b} + ${c}) = ${x}.`);}
const x=r(2,8),at=r(1,5),coefficient=x*at;return makeWordProblem(`A machine's output is f(t) = t². What is the instantaneous rate of change when t = ${at}?`,`La salida de una máquina es f(t) = t². ¿Cuál es la tasa de cambio instantánea cuando t = ${at}?`,2*at,[`Use the power rule: the derivative of t² is 2t.`,`Substitute t = ${at} into 2t.`],[`Usa la regla de la potencia: la derivada de t² es 2t.`,`Sustituye t = ${at} en 2t.`],`f′(t) = 2t, so f′(${at}) = ${2*at}.`,`f′(t) = 2t, por lo tanto f′(${at}) = ${2*at}.`);}
function freshWordProblem(){let next=createWordProblem(),attempts=0;while(next.prompt===currentWordProblem?.prompt&&attempts<8){next=createWordProblem();attempts++;}return next;}
function renderWordProblem(){const es=localStorage.getItem('numoraLanguage')==='es';if(!currentWordProblem)currentWordProblem=createWordProblem();pageTitle.textContent=es?'Taller de problemas':'Word problem workshop';content.innerHTML=`<div class="page-wrap word-problem-page"><div class="hero-row"><div><span class="eyebrow">${es?'PRACTICA CON HISTORIAS':'APPLY WHAT YOU KNOW'}</span><h1>${es?'Taller de problemas':'Word problem workshop'}</h1><p>${es?`Resuelve problemas de ${escapeHtmlText(selectedGrade)} con pistas paso a paso.`:`Solve ${escapeHtmlText(selectedGrade)} math stories with step-by-step hints.`}</p></div><div class="word-problem-score"><strong>${wordProblemScore}</strong><small>${es?'resueltos':'solved'}</small></div></div><section class="card word-problem-card"><span class="skill-tag">${escapeHtmlText(selectedGrade)} · ${es?'PROBLEMA':'WORD PROBLEM'}</span><h2>${escapeHtmlText(currentWordProblem.prompt)}</h2><div class="word-problem-hint" aria-live="polite">${wordProblemHintIndex?`<strong>${es?'Pista':'Hint'} ${wordProblemHintIndex}:</strong> ${escapeHtmlText(currentWordProblem.hints[wordProblemHintIndex-1])}`:`<span>${es?'Piensa en la operación que conecta los datos de la historia.':'Think about the operation that connects the story details.'}</span>`}</div><label for="word-problem-answer">${es?'Tu respuesta':'Your answer'}</label><div class="word-problem-answer-row"><input id="word-problem-answer" class="answer-input" inputmode="decimal" autocomplete="off" placeholder="${es?'Escribe un número':'Enter a number'}"><button type="button" class="primary-btn" data-word-problem="check">${es?'Comprobar':'Check answer'}</button></div><p class="word-problem-feedback" aria-live="polite"></p><div class="word-problem-controls"><button type="button" class="secondary-btn" data-word-problem="hint">${es?'Mostrar una pista':'Show a hint'}</button><button type="button" class="secondary-btn" data-word-problem="solution">${es?'Ver solución':'Show solution'}</button><button type="button" class="secondary-btn" data-word-problem="next">${es?'Otro problema':'New problem'} →</button></div><div class="word-problem-solution hidden" data-word-problem-solution><strong>${es?'Solución paso a paso':'Worked solution'}</strong><p>${escapeHtmlText(currentWordProblem.solution)}</p></div></section><p class="word-problem-note">${es?'Las respuestas correctas ganan 10 XP. Puedes pedir pistas cuando las necesites.':'Correct answers earn 10 XP. Use hints whenever you need them.'}</p></div>`;}
document.addEventListener('click',event=>{if(!(event.target instanceof Element))return;const nav=event.target.closest('[data-view="word-problems"]');if(nav){event.preventDefault();event.stopImmediatePropagation();currentWordProblem=freshWordProblem();wordProblemHintIndex=0;renderWordProblem();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));return;}const button=event.target.closest('[data-word-problem]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const action=button.dataset.wordProblem,es=localStorage.getItem('numoraLanguage')==='es';if(action==='next'){currentWordProblem=freshWordProblem();wordProblemHintIndex=0;renderWordProblem();return;}if(action==='hint'){if(wordProblemHintIndex<currentWordProblem.hints.length)wordProblemHintIndex++;renderWordProblem();return;}if(action==='solution'){content.querySelector('[data-word-problem-solution]')?.classList.remove('hidden');return;}if(action==='check'){const input=content.querySelector('#word-problem-answer'),feedback=content.querySelector('.word-problem-feedback');if(!input.value.trim()){feedback.textContent=es?'Escribe tu respuesta primero.':'Enter an answer first.';return;}wordProblemAttempts++;const correct=Number.isFinite(currentWordProblem.answer)&&Math.abs(Number(input.value)-currentWordProblem.answer)<.00001;if(correct){wordProblemScore++;setXpBalance(getXpBalance()+10);feedback.textContent=es?'¡Correcto! Ganaste 10 XP.':'Correct! You earned 10 XP.';input.disabled=true;button.disabled=true;content.querySelector('.word-problem-score strong').textContent=String(wordProblemScore);showToast(es?'¡Muy bien! +10 XP':'Nice work! +10 XP');}else feedback.textContent=es?'Aún no. Prueba otra vez o pide una pista.':'Not quite. Try again or ask for a hint.';}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target instanceof Element&&event.target.id==='word-problem-answer')content.querySelector('[data-word-problem="check"]')?.click();});

const fractionStudio={first:{numerator:1,denominator:2},second:{numerator:1,denominator:3},score:0,solved:false,feedback:''};
function fractionDenominators(){const grade=/^Grade (\d+)$/.exec(selectedGrade),n=grade?Number(grade[1]):0;return n<=2||selectedGrade==='Pre-K'||selectedGrade==='Kindergarten'?[2,4]:[2,3,4,5,6,8,10,12];}
function fractionBar(fraction,label){const parts=Array.from({length:fraction.denominator},(_,index)=>`<span class="fraction-bar-part ${index<fraction.numerator?'is-shaded':''}"></span>`).join('');return `<div class="fraction-bar" role="img" aria-label="${escapeHtmlText(label)}" style="grid-template-columns:repeat(${fraction.denominator},minmax(0,1fr))">${parts}</div>`;}
function fractionPicker(which,label,es){const fraction=fractionStudio[which],denominators=fractionDenominators();return `<section class="card fraction-panel"><h2>${label}</h2><div class="fraction-picker"><label>${es?'Numerador':'Numerator'}<select data-fraction-value="${which}-numerator">${Array.from({length:fraction.denominator+1},(_,n)=>`<option value="${n}" ${n===fraction.numerator?'selected':''}>${n}</option>`).join('')}</select></label><span aria-hidden="true">/</span><label>${es?'Denominador':'Denominator'}<select data-fraction-value="${which}-denominator">${denominators.map(d=>`<option value="${d}" ${d===fraction.denominator?'selected':''}>${d}</option>`).join('')}</select></label></div>${fractionBar(fraction,`${fraction.numerator} / ${fraction.denominator}`)}<strong class="fraction-label">${fraction.numerator}/${fraction.denominator}</strong></section>`;}
function renderFractionStudio(){const es=localStorage.getItem('numoraLanguage')==='es',first=fractionStudio.first,second=fractionStudio.second;pageTitle.textContent=es?'Estudio de fracciones':'Fraction studio';const firstLabel=es?'Primera fracción':'First fraction',secondLabel=es?'Segunda fracción':'Second fraction';content.innerHTML=`<div class="page-wrap fraction-studio-page"><div class="hero-row"><div><span class="eyebrow">${es?'EXPLORA LAS PARTES':'SEE THE PARTS'}</span><h1>${es?'Estudio de fracciones':'Fraction studio'}</h1><p>${es?'Ajusta los numeradores y denominadores, observa las partes y compara.':'Adjust numerators and denominators, see the parts, and compare.'}</p></div><div class="fraction-score"><strong>${fractionStudio.score}</strong><span>${es?'retos correctos':'correct challenges'}</span></div></div><div class="fraction-studio-grid">${fractionPicker('first',firstLabel,es)}${fractionPicker('second',secondLabel,es)}</div><section class="card fraction-comparison"><h2>${es?'¿Cuál fracción es mayor?':'Which fraction is greater?'}</h2><div class="fraction-choice-row"><button type="button" class="secondary-btn" data-fraction-choice="first" ${fractionStudio.solved?'disabled':''}>${es?'Primera':'First'}: ${first.numerator}/${first.denominator}</button><button type="button" class="secondary-btn" data-fraction-choice="equal" ${fractionStudio.solved?'disabled':''}>${es?'Son iguales':'They are equal'}</button><button type="button" class="secondary-btn" data-fraction-choice="second" ${fractionStudio.solved?'disabled':''}>${es?'Segunda':'Second'}: ${second.numerator}/${second.denominator}</button></div><p class="fraction-feedback" aria-live="polite">${escapeHtmlText(fractionStudio.feedback|| (es?'Compara las partes sombreadas y el tamaño de cada parte.':'Compare the shaded parts and the size of each part.'))}</p><div class="fraction-howto"><strong>${es?'Pista':'Hint'}:</strong> ${es?'Puedes comparar a/b y c/d multiplicando a × d y c × b.':'To compare a/b and c/d, compare a × d with c × b.'}</div><div class="fraction-controls"><button type="button" class="primary-btn" data-fraction-action="new">${es?'Nuevo reto':'New challenge'} →</button></div></section></div>`;}
function resetFractionChoice(){fractionStudio.solved=false;fractionStudio.feedback='';}
function prepareFractionStudio(){const ds=fractionDenominators();for(const key of ['first','second'])if(!ds.includes(fractionStudio[key].denominator)){const d=ds[key==='second'?Math.min(1,ds.length-1):0];fractionStudio[key].denominator=d;fractionStudio[key].numerator=Math.min(fractionStudio[key].numerator,d);}resetFractionChoice();}
function newFractionChallenge(){const ds=fractionDenominators(),chooseDen=()=>ds[Math.floor(Math.random()*ds.length)],d=chooseDen(),e=chooseDen();fractionStudio.first={numerator:Math.floor(Math.random()*(d+1)),denominator:d};fractionStudio.second={numerator:Math.floor(Math.random()*(e+1)),denominator:e};resetFractionChoice();}
document.addEventListener('click',event=>{if(!(event.target instanceof Element))return;const nav=event.target.closest('[data-view="fraction-studio"]');if(nav){event.preventDefault();event.stopImmediatePropagation();prepareFractionStudio();renderFractionStudio();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));return;}const choice=event.target.closest('[data-fraction-choice]'),action=event.target.closest('[data-fraction-action]');if(action){event.preventDefault();event.stopImmediatePropagation();newFractionChallenge();renderFractionStudio();return;}if(!choice)return;event.preventDefault();event.stopImmediatePropagation();if(fractionStudio.solved)return;const a=fractionStudio.first,b=fractionStudio.second,left=a.numerator*b.denominator,right=b.numerator*a.denominator,answer=left>right?'first':left<right?'second':'equal',es=localStorage.getItem('numoraLanguage')==='es';if(choice.dataset.fractionChoice===answer){fractionStudio.solved=true;fractionStudio.score++;fractionStudio.feedback=es?`¡Correcto! ${a.numerator} × ${b.denominator} = ${left} y ${b.numerator} × ${a.denominator} = ${right}. Ganaste 10 XP.`:`Correct! ${a.numerator} × ${b.denominator} = ${left} and ${b.numerator} × ${a.denominator} = ${right}. You earned 10 XP.`;setXpBalance(getXpBalance()+10);showToast(es?'¡Comparación correcta! +10 XP':'Correct comparison! +10 XP');}else fractionStudio.feedback=es?'Vuelve a mirar las partes sombreadas. Intenta comparar los productos cruzados.':'Look at the shaded parts again. Try comparing the cross-products.';renderFractionStudio();});

// Keep the core navigation and challenge controls responsive even when an older
// delegated click handler fails or another listener stops the event later.
document.addEventListener('click',event=>{
  if(!(event.target instanceof Element))return;
  const nav=event.target.closest('[data-view="reports"],[data-view="custom"],[data-view="badges"],[data-view="challenge"]');
  const actionButton=event.target.closest('[data-action]');
  const action=actionButton?.dataset.action;
  const customStart=event.target.closest('[onclick*="startCustomQuiz"]');
  if(!nav&&!customStart&&!['start-challenge','toggle-challenge-pause','retry-challenge','replay-challenge','skip-challenge','submit-challenge','custom-random-lesson','custom-next-lesson'].includes(action))return;
  event.preventDefault();event.stopImmediatePropagation();
  if(nav){
    if(nav.dataset.view==='reports')reportsView();
    else if(nav.dataset.view==='custom')customQuizView();
    else if(nav.dataset.view==='badges')badgesView();
    else {clearInterval(challengeTimer);challengeTimer=0;challengeView();}
    document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));
    return;
  }
  if(customStart||action==='start-custom-quiz'){startCustomQuiz();return;}
  if(action==='start-challenge'){startChallenge();return;}
  if(action==='retry-challenge'){startChallenge({duration:challengeDuration,mode:challengeMode,difficulty:challengeDifficulty});return;}
  if(action==='toggle-challenge-pause'){
    challengePaused=!challengePaused;
    const pauseButton=document.querySelector('[data-action="toggle-challenge-pause"]');
    if(pauseButton){pauseButton.textContent=challengePaused?'Resume timer':'Pause timer';pauseButton.setAttribute('aria-pressed',String(challengePaused));}
    ['.answer-input','[data-action="submit-challenge"]','[data-action="skip-challenge"]'].forEach(selector=>{const node=document.querySelector(selector);if(node)node.disabled=challengePaused;});
    return;
  }
  if(action==='replay-challenge'){
    const replay=actionButton,duration=document.querySelector('#challenge-duration'),mode=document.querySelector('#challenge-mode'),difficulty=document.querySelector('#challenge-difficulty');
    if(duration&&mode&&difficulty){duration.value=['30','60','90','120','180'].includes(replay.dataset.duration)?replay.dataset.duration:'60';mode.value=['mixed','addition','subtraction','multiplication','division'].includes(replay.dataset.mode)?replay.dataset.mode:'mixed';difficulty.value=['warmup','standard','stretch'].includes(replay.dataset.difficulty)?replay.dataset.difficulty:'standard';startChallenge();}
    return;
  }
  if(action==='skip-challenge'){challengeSkipped++;challengeStreak=0;challengeQuestion++;renderChallengeQuestion();return;}
  if(action==='submit-challenge'){
    const input=document.querySelector('.answer-input');if(!input||!input.value.trim())return;
    challengeAnswered++;
    if(Number(input.value)===challengeAnswer){challengeScore++;challengeStreak++;challengeBestStreak=Math.max(challengeBestStreak,challengeStreak);setXpBalance(getXpBalance()+10);showToast('Correct! +10 XP');if(challengeStreak%5===0){setXpBalance(getXpBalance()+25);showToast('5-answer streak! +25 bonus XP');}}
    else{challengeStreak=0;showToast(`Not quite! The answer was ${challengeAnswer}.`);}
    challengeQuestion++;renderChallengeQuestion();return;
  }
  if(action==='custom-random-lesson'||action==='custom-next-lesson'){
    const select=document.querySelector('#custom-lesson');if(!select)return;
    const names=gradeSkillNames[selectedGrade]||gradeSkillNames['Grade 6'];
    const lesson=action==='custom-next-lesson'?resumeLessonName():names[Math.floor(Math.random()*names.length)];
    if(names.includes(lesson)){select.value=lesson;select.dispatchEvent(new Event('change',{bubbles:true}));showToast(action==='custom-next-lesson'?'Your next lesson is ready.':'Random lesson picked!');}
  }
},true);
document.addEventListener('change',event=>{if(!(event.target instanceof Element)||!event.target.matches('[data-fraction-value]'))return;const [which,part]=event.target.dataset.fractionValue.split('-');const value=Number(event.target.value);if(which!=='first'&&which!=='second'||!Number.isInteger(value))return;fractionStudio[which][part]=value;if(part==='denominator')fractionStudio[which].numerator=Math.min(fractionStudio[which].numerator,value);resetFractionChoice();renderFractionStudio();});

const arrayLab={rows:3,columns:4,score:0,challenge:null};
function arrayLabLimit(){if(selectedGrade==='Pre-K'||selectedGrade==='Kindergarten')return 5;const match=selectedGrade.match(/Grade (\d+)/);return match?Math.min(12,Math.max(5,Number(match[1])+2)):12;}
function newArrayChallenge(){const limit=arrayLabLimit(),small=Math.min(4,limit);arrayLab.challenge={rows:Math.floor(Math.random()*small)+2,columns:Math.floor(Math.random()*small)+2,solved:false};}
function renderArrayLab(){const es=localStorage.getItem('numoraLanguage')==='es',limit=arrayLabLimit(),rows=Math.min(limit,Math.max(1,arrayLab.rows)),columns=Math.min(limit,Math.max(1,arrayLab.columns)),total=rows*columns;arrayLab.rows=rows;arrayLab.columns=columns;if(!arrayLab.challenge)newArrayChallenge();const challenge=arrayLab.challenge,answer=challenge.rows*challenge.columns;pageTitle.textContent=es?'Laboratorio de arreglos de multiplicación':'Multiplication array lab';content.innerHTML=`<div class="page-wrap array-lab-page"><div class="hero-row"><div><span class="eyebrow">${es?'MODELO VISUAL':'VISUAL MATH'}</span><h1>${es?'Laboratorio de arreglos de multiplicación':'Multiplication array lab'}</h1><p>${es?'Organiza puntos en filas y columnas, y conecta el arreglo con la suma repetida.':'Arrange dots in rows and columns, then connect the array to repeated addition.'}</p></div><div class="array-lab-score"><strong>${arrayLab.score}</strong><span>${es?'retos correctos':'challenges solved'}</span></div></div><div class="array-lab-workspace"><section class="card array-lab-controls"><h2>${es?'Construye un arreglo':'Build an array'}</h2><div class="array-lab-pickers"><label>${es?'Filas':'Rows'}<select data-array-size="rows">${Array.from({length:limit},(_,i)=>i+1).map(value=>`<option value="${value}" ${rows===value?'selected':''}>${value}</option>`).join('')}</select></label><label>${es?'Columnas':'Columns'}<select data-array-size="columns">${Array.from({length:limit},(_,i)=>i+1).map(value=>`<option value="${value}" ${columns===value?'selected':''}>${value}</option>`).join('')}</select></label></div><p class="array-lab-equation" aria-live="polite">${rows} × ${columns} = ${total}<br><span>${Array.from({length:rows},()=>columns).join(' + ')} = ${total}</span></p></section><section class="card array-lab-board"><h2>${es?'Mira las filas y columnas':'See the rows and columns'}</h2><div class="array-lab-grid-wrap"><div class="array-lab-grid" role="img" aria-label="${rows} ${es?'filas por':'rows by'} ${columns} ${es?'columnas, en total':'columns, total'} ${total}" style="grid-template-columns:repeat(${columns},minmax(12px,22px))">${Array.from({length:total},()=>'<span class="array-lab-dot" aria-hidden="true"></span>').join('')}</div></div><p>${es?`${rows} filas con ${columns} puntos en cada fila hacen ${total}.`:`${rows} rows with ${columns} dots in each row make ${total}.`}</p></section></div><section class="card array-lab-controls" style="margin-top:16px"><h2>${es?'Reto rápido':'Quick challenge'}</h2><p>${es?`¿Cuántos puntos hay en ${challenge.rows} filas de ${challenge.columns}?`:`How many dots are in ${challenge.rows} rows of ${challenge.columns}?`}</p><div class="array-lab-challenge"><input type="number" min="0" step="1" inputmode="numeric" aria-label="${es?'Tu respuesta':'Your answer'}" placeholder="${es?'Escribe el producto':'Enter the product'}" ${challenge.solved?'disabled':''}><button type="button" class="primary-btn" data-array-action="check" ${challenge.solved?'disabled':''}>${es?'Comprobar':'Check answer'}</button><p class="array-lab-feedback" aria-live="polite">${challenge.solved?(es?'¡Correcto! Ganaste 10 XP.':'Correct! You earned 10 XP.'):''}</p></div><button type="button" class="secondary-btn" data-array-action="new">${es?'Nuevo reto':'New challenge'} →</button></section></div>`;}
document.addEventListener('click',event=>{if(!(event.target instanceof Element))return;const nav=event.target.closest('[data-view="array-lab"]'),action=event.target.closest('[data-array-action]');if(nav){event.preventDefault();event.stopImmediatePropagation();arrayLab.challenge=null;renderArrayLab();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item===nav));return;}if(!action)return;event.preventDefault();event.stopImmediatePropagation();if(action.dataset.arrayAction==='new'){newArrayChallenge();renderArrayLab();return;}const input=content.querySelector('.array-lab-challenge input'),feedback=content.querySelector('.array-lab-feedback');if(!input||!feedback||arrayLab.challenge?.solved)return;if(!input.value.trim()){feedback.textContent=localStorage.getItem('numoraLanguage')==='es'?'Escribe una respuesta primero.':'Enter an answer first.';return;}if(Number(input.value)===arrayLab.challenge.rows*arrayLab.challenge.columns){arrayLab.challenge.solved=true;arrayLab.score++;setXpBalance(getXpBalance()+10);showToast(localStorage.getItem('numoraLanguage')==='es'?'¡Correcto! +10 XP':'Correct! +10 XP');}else feedback.textContent=localStorage.getItem('numoraLanguage')==='es'?'Cuenta las filas o suma las columnas. Inténtalo otra vez.':'Count the rows or add the columns. Try again.';renderArrayLab();},true);
document.addEventListener('change',event=>{if(!(event.target instanceof Element)||!event.target.matches('[data-array-size]'))return;const value=Number(event.target.value),limit=arrayLabLimit();if(!Number.isInteger(value)||value<1||value>limit)return;arrayLab[event.target.dataset.arraySize]=value;renderArrayLab();});
